window.W4_DASHBOARD_UNITS = [{"unit":1,"theme":"accountable – validate","cards":[{"w":"accountable","p":"adj.","d":"responsible for what you do and able to explain it","c":"負有責任的","s":"Parents are accountable for the safety of their young children at all times.","t":"父母隨時都要為年幼孩子的安全負責。"},{"w":"addictive","p":"adj.","d":"making you want more and unable to stop","c":"使人上癮的","s":"Video games can be so addictive that some teenagers play them all night.","t":"電玩可能令人上癮到有些青少年整晚都在玩。"},{"w":"agenda","p":"n.","d":"a list of things to be discussed or done","c":"議程；待辦事項","s":"The first item on the agenda for today's meeting is the school trip.","t":"今天會議議程的第一項是校外教學。"},{"w":"coin","p":"v.","d":"to invent a new word or phrase","c":"創造（新詞）","s":"Writers sometimes coin new words when no existing word fits their idea.","t":"當現有的字無法表達想法時，作家有時會創造新詞。"},{"w":"correlate","p":"v.","d":"to be connected in a way that one thing changes with another","c":"相關；有關聯","s":"Studies show that hours of sleep correlate closely with students' test scores.","t":"研究顯示睡眠時數與學生的考試成績密切相關。"},{"w":"depression","p":"n.","d":"a condition of feeling very sad and without hope for a long time","c":"憂鬱；憂鬱症","s":"After losing his job, he fell into a deep depression and stopped seeing his friends.","t":"失業後，他陷入嚴重的憂鬱，不再和朋友見面。"},{"w":"digital","p":"adj.","d":"using computer technology","c":"數位的","s":"Most people now take photos with digital cameras or phones instead of film.","t":"現在大多數人用數位相機或手機拍照，而不用底片。"},{"w":"importance","p":"n.","d":"the quality of being important","c":"重要性","s":"The doctor explained the importance of washing hands before every meal.","t":"醫生說明了每餐飯前洗手的重要性。"},{"w":"keyboard","p":"n.","d":"the set of keys you press to type on a computer","c":"鍵盤","s":"She typed the letter quickly on the keyboard of her laptop.","t":"她在筆電的鍵盤上很快地打完那封信。"},{"w":"loneliness","p":"n.","d":"the sad feeling of being alone","c":"孤獨；寂寞","s":"Many old people who live by themselves suffer from loneliness.","t":"許多獨居的老人飽受孤獨之苦。"},{"w":"media","p":"n.","d":"television, newspapers, radio, and the Internet as a group","c":"媒體","s":"The story was reported by the media all over the world.","t":"這則消息被全世界的媒體報導。"},{"w":"platform","p":"n.","d":"a website or system that people use to share or do things","c":"平台","s":"The company built an online platform where teachers can share their lessons.","t":"這家公司建立了一個讓老師分享課程的線上平台。"},{"w":"poor","p":"adj.","d":"not good in quality","c":"差的；不好的","s":"The players lost the game because of their poor teamwork.","t":"球員們因為團隊合作不佳而輸了比賽。"},{"w":"presence","p":"n.","d":"the fact of being in a place","c":"出席；在場","s":"The children behaved well in the presence of their grandparents.","t":"孩子們在祖父母面前表現得很乖。"},{"w":"subject","p":"v.","d":"to make someone experience something unpleasant","c":"使遭受","s":"The guards would subject the prisoners to long hours of hard work.","t":"守衛會讓囚犯遭受長時間的苦役。"},{"w":"surge","p":"n.","d":"a sudden large increase","c":"激增；湧現","s":"There was a surge in online shopping during the holiday season.","t":"假期期間網路購物量激增。"},{"w":"survey","p":"n.","d":"a set of questions that you ask many people to learn their opinions","c":"調查","s":"The school did a survey to find out what students think about homework.","t":"學校做了一項調查，了解學生對作業的看法。"},{"w":"target","p":"v.","d":"to aim something at a certain group of people","c":"以…為目標","s":"The new toy ads target children between five and ten years old.","t":"新的玩具廣告以五到十歲的兒童為目標。"},{"w":"trend","p":"n.","d":"a general change in the way people behave or things develop","c":"趨勢；潮流","s":"Working from home is a growing trend in many countries.","t":"在家工作在許多國家是日益成長的趨勢。"},{"w":"validate","p":"v.","d":"to prove that something is true or correct","c":"證實；確認","s":"More tests are needed to validate the results of the experiment.","t":"需要更多測試來證實實驗的結果。"}]},{"unit":2,"theme":"carbon – transport","cards":[{"w":"carbon","p":"n.","d":"a chemical element found in coal, diamonds, and all living things","c":"碳","s":"Diamonds and coal are both made of carbon, though they look very different.","t":"鑽石和煤都是由碳構成的，儘管它們看起來很不一樣。"},{"w":"carbon dioxide","p":"n.","d":"the gas that people breathe out and that is produced when things burn","c":"二氧化碳","s":"Trees take in carbon dioxide from the air and give out oxygen.","t":"樹木從空氣中吸收二氧化碳並釋放氧氣。"},{"w":"dust","p":"n.","d":"very small dry pieces of dirt","c":"灰塵","s":"The old books on the shelf were covered with a thick layer of dust.","t":"書架上的舊書覆蓋著厚厚一層灰塵。"},{"w":"emit","p":"v.","d":"to send out gas, light, heat, or sound","c":"排放；發出","s":"Old cars emit more smoke than new ones and make the air dirty.","t":"舊車比新車排放更多廢氣，讓空氣變髒。"},{"w":"enable","p":"v.","d":"to make it possible for someone to do something","c":"使能夠","s":"Glasses enable people with weak eyes to see clearly.","t":"眼鏡讓視力不好的人能看得清楚。"},{"w":"grind","p":"v.","d":"to crush something into very small pieces or powder","c":"磨碎","s":"The workers grind the coffee beans into powder every morning.","t":"工人們每天早上把咖啡豆磨成粉。"},{"w":"heal","p":"v.","d":"to become healthy again","c":"癒合；治癒","s":"A small cut on the finger will usually heal within a week.","t":"手指上的小傷口通常一週內就會癒合。"},{"w":"integrate","p":"v.","d":"to join things or people together so they become one","c":"整合；融入","s":"The school tries to integrate new students into class life as quickly as possible.","t":"學校努力讓新生盡快融入班級生活。"},{"w":"leading","p":"adj.","d":"most important or most successful","c":"主要的；領先的","s":"She is one of the leading scientists in the field of cancer research.","t":"她是癌症研究領域的頂尖科學家之一。"},{"w":"moreover","p":"adv.","d":"in addition to what has been said","c":"此外；而且","s":"The room is small; moreover, it has no windows.","t":"這個房間很小；此外，它沒有窗戶。"},{"w":"object","p":"v.","d":"to say that you do not agree with something","c":"反對","s":"Many parents object to the plan to end school one hour later.","t":"許多家長反對晚一小時放學的計畫。"},{"w":"pollutant","p":"n.","d":"a substance that makes air, water, or soil dirty","c":"污染物","s":"Smoke from factories is a major pollutant of the air in big cities.","t":"工廠的煙是大城市空氣的主要污染物。"},{"w":"powder","p":"n.","d":"a dry substance made of very small grains","c":"粉末","s":"Mix the milk powder with warm water before you feed the baby.","t":"餵寶寶前先把奶粉和溫水混合。"},{"w":"prompt","p":"v.","d":"to cause someone to do something","c":"促使；引起","s":"The accident may prompt the city to put a traffic light at the corner.","t":"這起事故可能促使市政府在轉角設置紅綠燈。"},{"w":"reject","p":"v.","d":"to refuse to accept something","c":"拒絕","s":"The company decided to reject his idea because it cost too much.","t":"公司決定拒絕他的構想，因為成本太高。"},{"w":"skeptic","p":"n.","d":"a person who doubts that something is true","c":"懷疑論者","s":"My uncle is a skeptic who does not believe anything he reads online.","t":"我叔叔是個懷疑論者，不相信他在網路上讀到的任何東西。"},{"w":"substance","p":"n.","d":"a solid, liquid, or gas","c":"物質","s":"The police found a white substance in the bag and sent it to the lab.","t":"警方在袋子裡發現一種白色物質，並送去實驗室。"},{"w":"substantially","p":"adv.","d":"by a large amount","c":"大幅地","s":"Prices have risen substantially this year, so many families are spending less.","t":"今年物價大幅上漲，所以許多家庭減少開銷。"},{"w":"ton","p":"n.","d":"a unit of weight equal to 1,000 kilograms","c":"噸","s":"An adult elephant can weigh more than one ton.","t":"一頭成年大象的體重可超過一噸。"},{"w":"transport","p":"n.","d":"a system for carrying people or goods from place to place","c":"運輸；交通工具","s":"Buses and trains are the cheapest forms of transport in this city.","t":"公車和火車是這座城市最便宜的交通工具。"}]},{"unit":3,"theme":"align – tunnel","cards":[{"w":"align","p":"v.","d":"to put things in a straight line or in agreement","c":"使對齊；使一致","s":"Please align the desks in five straight rows before the test.","t":"考試前請把書桌排成整齊的五排。"},{"w":"authority","p":"n.","d":"the power to give orders and make decisions","c":"權力；權威","s":"Only the principal has the authority to close the school.","t":"只有校長有權力關閉學校。"},{"w":"barn","p":"n.","d":"a large farm building for animals or crops","c":"穀倉","s":"The farmer keeps his cows and hay in the big red barn.","t":"農夫把乳牛和乾草放在那座紅色大穀倉裡。"},{"w":"betray","p":"v.","d":"to hurt someone who trusts you by helping their enemy","c":"背叛","s":"A true friend would never betray you by telling your secrets.","t":"真正的朋友絕不會說出你的秘密來背叛你。"},{"w":"Bible","p":"n.","d":"the holy book of the Christian religion","c":"聖經","s":"The priest read a story from the Bible during the church service.","t":"神父在教堂禮拜中讀了一段聖經故事。"},{"w":"Catholic","p":"adj.","d":"belonging to the part of the Christian church led by the Pope","c":"天主教的","s":"She went to a Catholic school, where nuns taught many of the classes.","t":"她讀的是天主教學校，許多課由修女教授。"},{"w":"cooperate","p":"v.","d":"to work together with someone","c":"合作","s":"The two teams agreed to cooperate on the science project.","t":"兩個小組同意在科學專題上合作。"},{"w":"detain","p":"v.","d":"to keep someone in a place and not let them leave","c":"拘留；扣留","s":"The police can detain a person for one day while they ask questions.","t":"警方可以拘留一個人一天以進行訊問。"},{"w":"exit","p":"n.","d":"a door or way out of a place","c":"出口","s":"In case of fire, walk calmly to the nearest exit.","t":"發生火災時，請冷靜地走向最近的出口。"},{"w":"exceptional","p":"adj.","d":"much better than usual","c":"傑出的；特殊的","s":"She is an exceptional student who finished high school at fifteen.","t":"她是個傑出的學生，十五歲就高中畢業。"},{"w":"flee","p":"v.","d":"to run away from danger","c":"逃離","s":"Thousands of people had to flee their homes during the war.","t":"戰爭期間數千人不得不逃離家園。"},{"w":"network","p":"n.","d":"a system of things or people that are connected","c":"網絡；網路","s":"The city has a large network of buses and subway lines.","t":"這座城市有龐大的公車和地鐵路網。"},{"w":"outrage","p":"v.","d":"to make someone very angry or shocked","c":"激怒","s":"The decision to cut down the old trees will outrage people in the town.","t":"砍掉老樹的決定將激怒鎮上的居民。"},{"w":"parish","p":"n.","d":"an area that has its own church and priest","c":"教區","s":"Everyone in the parish came to the church for the Christmas service.","t":"教區裡的每個人都來教堂參加聖誕禮拜。"},{"w":"passage","p":"n.","d":"a long, narrow way through something","c":"通道；走道","s":"A secret passage led from the castle to the river.","t":"一條秘密通道從城堡通往河邊。"},{"w":"pastor","p":"n.","d":"a minister in charge of a Christian church","c":"牧師","s":"The pastor visits sick members of his church every week.","t":"牧師每週探望教會裡生病的教友。"},{"w":"patrol","p":"n.","d":"the act of going around an area to check that it is safe","c":"巡邏；巡邏隊","s":"Two police officers are on patrol in this neighborhood every night.","t":"每晚有兩名警察在這個社區巡邏。"},{"w":"raid","p":"v.","d":"to attack or enter a place suddenly","c":"突襲；搜查","s":"The police plan to raid the building where the stolen cars are hidden.","t":"警方計畫突襲藏匿贓車的那棟建築。"},{"w":"rail","p":"n.","d":"one of the metal bars that trains run on; a bar to hold on to","c":"鐵軌；欄杆","s":"Hold on to the rail when you walk down the wet stairs.","t":"走下濕滑的樓梯時要扶著欄杆。"},{"w":"tunnel","p":"n.","d":"a long passage under the ground or through a mountain","c":"隧道","s":"The train passed through a dark tunnel under the mountain.","t":"火車穿過山底下一條黑暗的隧道。"}]},{"unit":4,"theme":"comfortable – workplace","cards":[{"w":"comfortable","p":"adj.","d":"feeling relaxed and without pain or worry","c":"舒適的；自在的","s":"This sofa is so comfortable that I often fall asleep on it.","t":"這張沙發舒服到我常常在上面睡著。"},{"w":"education","p":"n.","d":"the process of teaching and learning","c":"教育","s":"Every child has the right to a good education.","t":"每個孩子都有接受良好教育的權利。"},{"w":"encouragement","p":"n.","d":"words or actions that give someone hope or confidence","c":"鼓勵","s":"With her teacher's encouragement, she entered the speech contest and won.","t":"在老師的鼓勵下，她參加演講比賽並獲勝。"},{"w":"endorse","p":"v.","d":"to say publicly that you support someone or something","c":"支持；認可","s":"Many doctors endorse the plan to ban smoking in public places.","t":"許多醫生支持在公共場所禁菸的計畫。"},{"w":"equal","p":"adj.","d":"the same in size, number, or rights","c":"平等的；相等的","s":"Men and women should receive equal pay for the same work.","t":"男女同工應該同酬。"},{"w":"face","p":"v.","d":"to deal with a difficult situation","c":"面對","s":"Many young people face the problem of finding a good job.","t":"許多年輕人面對找到好工作的難題。"},{"w":"field","p":"n.","d":"an area of study or work","c":"領域","s":"She is an expert in the field of children's health.","t":"她是兒童健康領域的專家。"},{"w":"foster","p":"v.","d":"to help something develop","c":"培養；促進","s":"Reading to children helps foster their love of books.","t":"唸書給孩子聽有助於培養他們對書本的喜愛。"},{"w":"guidance","p":"n.","d":"help and advice about what to do","c":"指導；引導","s":"Students can ask the counselor for guidance about choosing a college.","t":"學生可以向輔導老師尋求選擇大學的指導。"},{"w":"hold","p":"v.","d":"to have a job, position, or title","c":"擔任；擁有","s":"Women now hold many of the top jobs in the company.","t":"現在公司裡許多高層職位由女性擔任。"},{"w":"inclusion","p":"n.","d":"the act of making someone part of a group","c":"包容；納入","s":"The school believes in the inclusion of students with special needs in every class.","t":"這所學校主張把有特殊需求的學生納入每個班級。"},{"w":"inspire","p":"v.","d":"to make someone want to do something great","c":"激勵；啟發","s":"Great teachers inspire their students to work hard and dream big.","t":"優秀的老師激勵學生努力學習、勇於追夢。"},{"w":"mere","p":"adj.","d":"nothing more than","c":"僅僅的；只不過的","s":"He finished the whole test in a mere ten minutes.","t":"他僅僅用十分鐘就寫完整份考卷。"},{"w":"position","p":"n.","d":"a job in a company or organization","c":"職位","s":"She applied for the position of manager at the new store.","t":"她應徵新店的經理職位。"},{"w":"power","p":"n.","d":"the ability to control people and events","c":"權力","s":"The king had the power to make and change all the laws.","t":"國王有制定和修改所有法律的權力。"},{"w":"responsibility","p":"n.","d":"a duty to take care of someone or something","c":"責任","s":"Feeding the dog every day is my responsibility at home.","t":"每天餵狗是我在家裡的責任。"},{"w":"soar","p":"v.","d":"to rise very quickly or fly high in the air","c":"高飛；猛增","s":"House prices in the city continue to soar every year.","t":"這座城市的房價每年持續飆漲。"},{"w":"tool","p":"n.","d":"a thing that helps you do a job","c":"工具","s":"A hammer is the right tool for hitting nails into wood.","t":"鐵鎚是把釘子敲進木頭的合適工具。"},{"w":"vocal","p":"adj.","d":"expressing opinions freely and loudly","c":"直言不諱的","s":"The students were very vocal about their dislike of the new uniform.","t":"學生們非常直率地表達他們不喜歡新制服。"},{"w":"workplace","p":"n.","d":"the place where people work","c":"工作場所","s":"Smoking is not allowed in the workplace or in any office building.","t":"工作場所和任何辦公大樓都禁止吸菸。"}]},{"unit":5,"theme":"academic – width","cards":[{"w":"academic","p":"adj.","d":"relating to school and study","c":"學術的；學業的","s":"Her academic record is excellent; she has never had a grade below 90.","t":"她的學業成績優異，從未低於九十分。"},{"w":"acceptance","p":"n.","d":"the act of agreeing to or approving of something","c":"接受；認可","s":"His new idea slowly gained acceptance among the other scientists.","t":"他的新想法慢慢獲得其他科學家的認可。"},{"w":"array","p":"n.","d":"a large group of things arranged in an attractive way","c":"一系列；大量","s":"The market offers a wide array of fresh fruit and vegetables.","t":"這個市場提供各式各樣的新鮮蔬果。"},{"w":"blur","p":"v.","d":"to make something difficult to see clearly","c":"使模糊","s":"Tears began to blur her eyes as she read the sad letter.","t":"她讀那封悲傷的信時，淚水開始模糊了她的雙眼。"},{"w":"café","p":"n.","d":"a small restaurant that serves drinks and light meals","c":"咖啡館","s":"We met at a café near the station and talked over coffee.","t":"我們在車站附近的咖啡館見面，邊喝咖啡邊聊。"},{"w":"canvas","p":"n.","d":"a strong cloth that artists paint on","c":"畫布；帆布","s":"The artist painted a picture of the sea on a large white canvas.","t":"藝術家在一大塊白色畫布上畫了一幅海景。"},{"w":"cinema","p":"n.","d":"a place where people go to watch movies","c":"電影院","s":"We went to the cinema to see the new action movie on the big screen.","t":"我們去電影院在大銀幕上看那部新動作片。"},{"w":"class","p":"n.","d":"a group of people in society with the same level of money or position","c":"階級","s":"In the past, only people of the upper class could afford to travel.","t":"過去只有上層階級的人才負擔得起旅行。"},{"w":"distinctive","p":"adj.","d":"having a quality that makes something easy to recognize","c":"獨特的；有特色的","s":"The singer has a distinctive voice that you can recognize at once.","t":"那位歌手有獨特的嗓音，你一聽就認得出來。"},{"w":"key","p":"adj.","d":"most important","c":"關鍵的；主要的","s":"Hard work is the key factor in his success.","t":"努力是他成功的關鍵因素。"},{"w":"movement","p":"n.","d":"a group of people who share the same ideas and work together","c":"（藝術或社會）運動","s":"She joined a movement to protect the rights of animals.","t":"她加入了一個保護動物權利的運動。"},{"w":"practice","p":"n.","d":"a usual way of doing something","c":"慣例；做法","s":"It is common practice in Japan to take off your shoes at the door.","t":"在日本，進門脫鞋是常見的做法。"},{"w":"realistic","p":"adj.","d":"showing things as they really are","c":"寫實的；實際的","s":"The painting is so realistic that it looks like a photograph.","t":"這幅畫非常寫實，看起來就像照片。"},{"w":"reflection","p":"n.","d":"an image that you see in a mirror or in water","c":"倒影；映像","s":"The cat looked at its own reflection in the mirror and jumped back.","t":"那隻貓看著鏡中自己的倒影，嚇得往後跳。"},{"w":"rule","p":"n.","d":"a statement of what you must or must not do","c":"規則","s":"The first rule of the library is that you must be quiet.","t":"圖書館的第一條規則是必須保持安靜。"},{"w":"stroke","p":"n.","d":"a single movement of a pen or brush","c":"筆觸；一筆","s":"With one stroke of his brush, the artist turned the line into a bird.","t":"藝術家只用一筆就把那條線變成一隻鳥。"},{"w":"sunlight","p":"n.","d":"the light from the sun","c":"陽光","s":"Plants need water and sunlight to grow well.","t":"植物需要水和陽光才能長得好。"},{"w":"traditional","p":"adj.","d":"following ideas and customs that have existed for a long time","c":"傳統的","s":"The dancers wore traditional clothes that their grandmothers had made.","t":"舞者們穿著祖母親手做的傳統服飾。"},{"w":"unlike","p":"prep.","d":"different from","c":"不像；和…不同","s":"Unlike his noisy brother, Tom is quiet and shy.","t":"和他吵鬧的哥哥不同，湯姆安靜又害羞。"},{"w":"width","p":"n.","d":"the distance from one side of something to the other","c":"寬度","s":"Please measure the width of the door to see if the sofa will fit through it.","t":"請量一下門的寬度，看沙發能不能搬過去。"}]},{"unit":6,"theme":"anthem – wound","cards":[{"w":"anthem","p":"n.","d":"the official song of a country","c":"國歌；頌歌","s":"Everyone stood up when the national anthem was played before the game.","t":"比賽前播放國歌時，所有人都起立。"},{"w":"beyond","p":"prep.","d":"on the far side of something","c":"在…之外；超出","s":"The village lies beyond those mountains, a two-day walk from here.","t":"那個村莊在那些山的另一邊，從這裡要走兩天。"},{"w":"determination","p":"n.","d":"the quality of trying to do something even when it is hard","c":"決心","s":"With great determination, she learned to walk again after the accident.","t":"憑著極大的決心，她在事故後重新學會走路。"},{"w":"fighting","p":"n.","d":"the act of people or armies trying to hurt each other","c":"戰鬥；打鬥","s":"Heavy fighting continued in the city for three days and nights.","t":"激烈的戰鬥在城裡持續了三天三夜。"},{"w":"joint","p":"adj.","d":"shared or done by two or more people","c":"共同的；聯合的","s":"The two schools held a joint concert to raise money for the hospital.","t":"兩所學校舉辦聯合音樂會為醫院募款。"},{"w":"landing","p":"n.","d":"the act of arriving on land from the sea or air","c":"登陸；降落","s":"The pilot made a safe landing in spite of the strong wind.","t":"儘管風很大，飛行員仍安全降落。"},{"w":"mark","p":"v.","d":"to show that something important has happened","c":"標誌；紀念","s":"A big parade will mark the hundredth birthday of the city.","t":"一場盛大的遊行將紀念這座城市建城一百週年。"},{"w":"mobilize","p":"v.","d":"to organize people to work together for a purpose","c":"動員","s":"The mayor tried to mobilize volunteers to clean up after the flood.","t":"市長設法動員志工在水災後協助清理。"},{"w":"nation","p":"n.","d":"a country and its people","c":"國家","s":"The whole nation watched the final game on television.","t":"全國人民都在電視上觀看決賽。"},{"w":"originally","p":"adv.","d":"in the beginning","c":"原本；起初","s":"The building was originally a factory, but now it is a museum.","t":"這棟建築原本是工廠，但現在是博物館。"},{"w":"outbreak","p":"n.","d":"the sudden start of something bad, such as war or disease","c":"爆發","s":"Schools were closed after an outbreak of flu in the city.","t":"城裡爆發流感後，學校停課了。"},{"w":"pray","p":"v.","d":"to speak to God to give thanks or ask for help","c":"祈禱","s":"The villagers pray for rain every morning during the dry season.","t":"旱季期間，村民每天早上祈求下雨。"},{"w":"prisoner","p":"n.","d":"a person who is kept in prison or caught by an enemy","c":"囚犯；俘虜","s":"The prisoner was kept in a small cell for ten years.","t":"那名囚犯被關在小牢房裡十年。"},{"w":"sacrifice","p":"v.","d":"to give up something important for a good reason","c":"犧牲","s":"Many parents sacrifice their own comfort to give their children a better life.","t":"許多父母犧牲自己的舒適，給孩子更好的生活。"},{"w":"silence","p":"n.","d":"a complete lack of sound","c":"寂靜；沉默","s":"There was complete silence in the room when the teacher walked in.","t":"老師走進來時，教室裡一片寂靜。"},{"w":"thus","p":"adv.","d":"as a result of this","c":"因此","s":"He studied hard every day and thus passed the exam easily.","t":"他每天努力讀書，因此輕鬆通過考試。"},{"w":"tribute","p":"n.","d":"something you say or do to show respect for someone","c":"致敬；讚頌","s":"The concert was a tribute to the singer, who died last year.","t":"這場音樂會是向去年過世的那位歌手致敬。"},{"w":"victory","p":"n.","d":"success in a game, fight, or war","c":"勝利","s":"The team celebrated its victory with a big party.","t":"球隊舉辦盛大的派對慶祝勝利。"},{"w":"wild","p":"adv.","d":"in a way that is not controlled","c":"狂野地；失控地","s":"The fans went wild when their team scored in the last minute.","t":"球隊在最後一分鐘得分時，球迷們都瘋狂了。"},{"w":"wound","p":"v.","d":"to hurt someone with a weapon","c":"使受傷","s":"The bullets did not kill the soldier, but they did wound him badly.","t":"子彈沒有殺死那名士兵，但確實讓他受了重傷。"}]},{"unit":7,"theme":"assimilate – urban","cards":[{"w":"assimilate","p":"v.","d":"to become part of a group or country and its culture","c":"同化；融入","s":"It can take many years for newcomers to assimilate into a new country.","t":"新移民可能需要很多年才能融入一個新國家。"},{"w":"attempt","p":"n.","d":"an act of trying to do something","c":"嘗試；企圖","s":"He passed his driving test on the third attempt.","t":"他第三次嘗試才通過駕照考試。"},{"w":"case","p":"n.","d":"a situation or example of something","c":"情況；實例","s":"In this case, I think we should call the police.","t":"在這種情況下，我認為我們應該報警。"},{"w":"cease","p":"v.","d":"to stop happening or doing something","c":"停止","s":"The factory will cease making cars at the end of the year.","t":"這家工廠將在年底停止生產汽車。"},{"w":"danger","p":"n.","d":"the possibility that someone will be hurt or killed","c":"危險","s":"The sign warns swimmers of the danger of strong waves.","t":"告示牌警告泳客大浪的危險。"},{"w":"devastating","p":"adj.","d":"causing great damage or sadness","c":"毀滅性的","s":"The devastating fire destroyed half of the old town in one night.","t":"那場毀滅性的大火一夜之間燒毀半個老城。"},{"w":"diversity","p":"n.","d":"the fact of including many different kinds of people or things","c":"多樣性","s":"The rain forest has a great diversity of plants and animals.","t":"雨林有極為多樣的動植物。"},{"w":"earthquake","p":"n.","d":"a sudden shaking of the ground","c":"地震","s":"The earthquake shook the buildings and broke many windows.","t":"地震搖晃了建築物，震破許多窗戶。"},{"w":"endangered","p":"adj.","d":"in danger of disappearing from the earth","c":"瀕臨絕種的","s":"The panda is an endangered animal, with fewer than two thousand left in the wild.","t":"熊貓是瀕臨絕種的動物，野外僅剩不到兩千隻。"},{"w":"extinction","p":"n.","d":"the state of no longer existing","c":"滅絕","s":"Hunting has brought some kinds of whales close to extinction.","t":"捕獵使某些鯨魚瀕臨滅絕。"},{"w":"forever","p":"adv.","d":"for all time","c":"永遠","s":"I will remember this wonderful day forever.","t":"我會永遠記得這美好的一天。"},{"w":"generally","p":"adv.","d":"usually; in most cases","c":"通常；一般地","s":"Children generally start elementary school at the age of six.","t":"孩子通常六歲開始上小學。"},{"w":"genocide","p":"n.","d":"the killing of a whole group of people","c":"種族滅絕","s":"The world must never forget the genocide of millions during the war.","t":"世人絕不能忘記戰爭期間數百萬人遭到種族滅絕。"},{"w":"hit","p":"v.","d":"to affect a place or person badly","c":"侵襲；打擊","s":"A strong typhoon will hit the east coast tomorrow night.","t":"強烈颱風明晚將侵襲東海岸。"},{"w":"lose","p":"v.","d":"to no longer have something","c":"失去","s":"Many small languages lose speakers every year as young people move to cities.","t":"隨著年輕人搬到城市，許多小語種每年都失去使用者。"},{"w":"native","p":"adj.","d":"connected with the place where you were born","c":"本地的；母語的","s":"Her native language is Spanish, but she also speaks English well.","t":"她的母語是西班牙語，但英語也說得很好。"},{"w":"percent","p":"n.","d":"one part in every hundred","c":"百分比","s":"About seventy percent of the earth is covered by water.","t":"地球表面約百分之七十被水覆蓋。"},{"w":"reason","p":"n.","d":"why something happens or why someone does something","c":"原因；理由","s":"The reason for his absence was a bad cold.","t":"他缺席的原因是重感冒。"},{"w":"reference","p":"n.","d":"the act of mentioning something","c":"提及；參考","s":"The speaker made no reference to the accident in his talk.","t":"演講者在談話中沒有提到那起事故。"},{"w":"urban","p":"adj.","d":"relating to a city","c":"都市的","s":"More than half of the world's people now live in urban areas.","t":"現在全世界超過一半的人口住在都市地區。"}]},{"unit":8,"theme":"burn – summary","cards":[{"w":"burn","p":"v.","d":"to use something as fuel or energy","c":"燃燒（熱量）","s":"Running for thirty minutes can burn about three hundred calories.","t":"跑步三十分鐘可以燃燒大約三百卡路里。"},{"w":"check","p":"v.","d":"to look at something to make sure it is right","c":"檢查","s":"Please check your answers before you hand in the test.","t":"交卷前請檢查你的答案。"},{"w":"coconut","p":"n.","d":"a large fruit with a hard brown shell, white flesh, and liquid inside","c":"椰子","s":"He cut open a coconut and drank the sweet water inside.","t":"他切開一顆椰子，喝裡面甜甜的汁。"},{"w":"epilepsy","p":"n.","d":"a brain disease that makes a person suddenly lose control of the body","c":"癲癇","s":"People with epilepsy take medicine to prevent sudden attacks.","t":"癲癇患者服藥以預防突然發作。"},{"w":"fat","p":"n.","d":"the oily substance in food or under the skin","c":"脂肪","s":"Fried food contains a lot of fat, so you should not eat it every day.","t":"油炸食物含有大量脂肪，所以不該天天吃。"},{"w":"gain","p":"n.","d":"an increase in amount, weight, or value","c":"增加；獲益","s":"The doctor was worried about the baby's slow weight gain.","t":"醫生擔心寶寶體重增加緩慢。"},{"w":"glucose","p":"n.","d":"a natural sugar that gives the body energy","c":"葡萄糖","s":"The body turns bread and rice into glucose for energy.","t":"身體把麵包和米飯轉化成葡萄糖作為能量。"},{"w":"high","p":"adj.","d":"containing a lot of something; greater than usual","c":"高的；含量高的","s":"Nuts are high in fat, but it is the healthy kind.","t":"堅果脂肪含量高，但那是健康的脂肪。"},{"w":"keep","p":"v.","d":"to stay in a certain state","c":"保持","s":"Regular exercise helps you keep healthy and strong.","t":"規律運動幫助你保持健康強壯。"},{"w":"known","p":"adj.","d":"familiar to many people","c":"知名的；已知的","s":"He is the best known singer in the country.","t":"他是全國最知名的歌手。"},{"w":"liver","p":"n.","d":"the organ in the body that cleans the blood","c":"肝臟","s":"Drinking too much alcohol can damage the liver.","t":"飲酒過量會損害肝臟。"},{"w":"low","p":"n.","d":"a low level or point","c":"低點","s":"The temperature fell to a record low of minus ten degrees last night.","t":"昨晚氣溫降到零下十度的歷史低點。"},{"w":"management","p":"n.","d":"the act of controlling or dealing with something","c":"管理","s":"Good time management helps students finish their homework early.","t":"良好的時間管理幫助學生早點完成作業。"},{"w":"metabolic","p":"adj.","d":"relating to the way the body turns food into energy","c":"新陳代謝的","s":"Exercise raises your metabolic rate, so your body uses energy faster.","t":"運動會提高你的新陳代謝率，讓身體更快消耗能量。"},{"w":"oil","p":"n.","d":"a thick liquid used for cooking","c":"油","s":"Heat some oil in the pan before you fry the fish.","t":"煎魚前先在鍋裡熱一點油。"},{"w":"olive","p":"n.","d":"a small green or black fruit that is eaten or used to make oil","c":"橄欖","s":"She put a green olive on top of each small sandwich.","t":"她在每個小三明治上放一顆綠橄欖。"},{"w":"performance","p":"n.","d":"how well a person or machine does something","c":"表現","s":"The coach was pleased with the team's performance in the final game.","t":"教練對球隊在決賽的表現很滿意。"},{"w":"powerful","p":"adj.","d":"having great strength or a strong effect","c":"強大的；強效的","s":"This medicine is very powerful, so take only one pill a day.","t":"這種藥藥效很強，所以一天只能吃一顆。"},{"w":"starch","p":"n.","d":"a white substance found in foods such as rice, bread, and potatoes","c":"澱粉","s":"Potatoes and rice contain a lot of starch.","t":"馬鈴薯和米飯含有大量澱粉。"},{"w":"summary","p":"n.","d":"a short statement that gives the main points","c":"摘要；總結","s":"Please write a one-page summary of the story you read.","t":"請為你讀的故事寫一頁摘要。"}]},{"unit":9,"theme":"analytic – weak","cards":[{"w":"analytic","p":"adj.","d":"using careful thinking to understand something","c":"分析的","s":"A detective needs an analytic mind to solve difficult crimes.","t":"偵探需要善於分析的頭腦來偵破困難的案件。"},{"w":"area","p":"n.","d":"a subject or part of an activity","c":"領域；方面","s":"Math is the area in which she needs the most help.","t":"數學是她最需要幫助的領域。"},{"w":"bachelor","p":"n.","d":"a person with a first university degree","c":"學士","s":"She earned a bachelor of science degree after four years of college.","t":"她讀了四年大學後取得理學士學位。"},{"w":"cognitive","p":"adj.","d":"connected with thinking and understanding","c":"認知的","s":"Puzzles and reading help children develop their cognitive skills.","t":"拼圖和閱讀幫助孩子發展認知能力。"},{"w":"collision","p":"n.","d":"an accident in which two things hit each other","c":"碰撞","s":"Two people were hurt in a collision between a bus and a truck.","t":"公車與卡車相撞，造成兩人受傷。"},{"w":"competent","p":"adj.","d":"able to do something well","c":"有能力的；勝任的","s":"We need a competent driver who has never had an accident.","t":"我們需要一位從未出過事故的稱職司機。"},{"w":"diploma","p":"n.","d":"a paper that shows you have finished a course of study","c":"文憑；畢業證書","s":"She proudly hung her high school diploma on the wall.","t":"她驕傲地把高中畢業證書掛在牆上。"},{"w":"excel","p":"v.","d":"to be very good at something","c":"擅長；表現優異","s":"Some students excel at sports, while others are better at art.","t":"有些學生擅長運動，有些則美術較好。"},{"w":"geology","p":"n.","d":"the study of rocks and the earth","c":"地質學","s":"In geology class, we learned how mountains are formed.","t":"在地質學課上，我們學到山脈如何形成。"},{"w":"integral","p":"adj.","d":"necessary as a part of something","c":"不可或缺的","s":"Music is an integral part of every wedding in this village.","t":"音樂是這個村莊每場婚禮不可或缺的一部分。"},{"w":"intellect","p":"n.","d":"the ability to think and understand","c":"智力；才智","s":"The professor is a woman of great intellect who has written twenty books.","t":"那位教授才智過人，寫過二十本書。"},{"w":"job","p":"n.","d":"the work that a person does to earn money","c":"工作","s":"He found a job at a bank right after college.","t":"他大學一畢業就在銀行找到工作。"},{"w":"keen","p":"adj.","d":"very interested or eager","c":"熱衷的；敏銳的","s":"He is a keen student of history and reads about it every night.","t":"他熱衷研讀歷史，每晚都閱讀相關書籍。"},{"w":"minimum","p":"adj.","d":"the smallest that is possible or allowed","c":"最低的；最小的","s":"The minimum age for driving a car in Taiwan is eighteen.","t":"在台灣開車的最低年齡是十八歲。"},{"w":"psychology","p":"n.","d":"the study of the mind and how people behave","c":"心理學","s":"She studies psychology because she wants to understand why people act as they do.","t":"她研讀心理學，因為想了解人為何有這樣的行為。"},{"w":"radioactive","p":"adj.","d":"sending out a harmful form of energy","c":"放射性的","s":"The workers wore special suits to protect them from radioactive waste.","t":"工人穿著特殊防護衣以防放射性廢料。"},{"w":"relativity","p":"n.","d":"Einstein's theory about space, time, and movement","c":"相對論","s":"Einstein's theory of relativity changed our ideas about time and space.","t":"愛因斯坦的相對論改變了我們對時間和空間的看法。"},{"w":"sociology","p":"n.","d":"the study of society and how people live together","c":"社會學","s":"In sociology class, students discuss problems such as poverty and crime.","t":"在社會學課上，學生討論貧窮和犯罪等問題。"},{"w":"theoretical","p":"adj.","d":"based on ideas rather than practice","c":"理論的","s":"The course is mostly theoretical, with very little time spent in the lab.","t":"這門課以理論為主，很少時間待在實驗室。"},{"w":"weak","p":"adj.","d":"not good at something","c":"弱的；不擅長的","s":"I am good at English but weak in math and science.","t":"我英文很好，但數學和自然不擅長。"}]},{"unit":10,"theme":"administrator – violate","cards":[{"w":"administrator","p":"n.","d":"a person whose job is to manage an organization","c":"行政人員；管理者","s":"The hospital administrator is in charge of the budget and the staff.","t":"醫院的行政主管負責預算和員工。"},{"w":"affluent","p":"adj.","d":"having a lot of money","c":"富裕的","s":"Most families in this affluent neighborhood own two or three cars.","t":"這個富裕社區的大多數家庭擁有兩三輛車。"},{"w":"audit","p":"v.","d":"to check a company's financial records officially","c":"查帳；審計","s":"The government will audit the company's accounts next month.","t":"政府下個月將查核這家公司的帳目。"},{"w":"automate","p":"v.","d":"to use machines to do work instead of people","c":"使自動化","s":"The factory plans to automate the whole process and use robots.","t":"工廠計畫把整個流程自動化並使用機器人。"},{"w":"bribe","p":"n.","d":"money given to someone to make them do something dishonest","c":"賄賂","s":"The police officer refused to take a bribe from the driver.","t":"那位警察拒絕收受駕駛的賄賂。"},{"w":"corrupt","p":"adj.","d":"using power in a dishonest way to get money","c":"腐敗的；貪污的","s":"The corrupt official was sent to prison for stealing public money.","t":"那名貪污的官員因竊取公款而入獄。"},{"w":"dispose","p":"v.","d":"to get rid of something","c":"處理；丟棄","s":"Please dispose of your trash in the bin, not on the ground.","t":"請把垃圾丟進垃圾桶，不要丟在地上。"},{"w":"headquarters","p":"n.","d":"the main office of a company or organization","c":"總部","s":"The company's headquarters is in Taipei, but it has offices in ten countries.","t":"這家公司的總部在台北，但在十個國家設有辦事處。"},{"w":"incentive","p":"n.","d":"something that makes you want to do something","c":"誘因；獎勵","s":"The free gift is an incentive for customers to buy more.","t":"免費贈品是吸引顧客多買的誘因。"},{"w":"infrastructure","p":"n.","d":"the basic systems of a country, such as roads, power, and water","c":"基礎建設","s":"The government spent billions on infrastructure such as roads and bridges.","t":"政府投入數十億於道路和橋樑等基礎建設。"},{"w":"legislate","p":"v.","d":"to make a new law","c":"立法","s":"The government plans to legislate against smoking in cars with children.","t":"政府計畫立法禁止在載有兒童的車內吸菸。"},{"w":"legitimate","p":"adj.","d":"allowed by law; fair and reasonable","c":"合法的；正當的","s":"Being sick is a legitimate reason for missing school.","t":"生病是缺課的正當理由。"},{"w":"manipulate","p":"v.","d":"to control someone in a clever and unfair way","c":"操縱","s":"Some ads try to manipulate children into wanting toys they do not need.","t":"有些廣告試圖操縱兒童，讓他們想要不需要的玩具。"},{"w":"merchandise","p":"n.","d":"things that are bought and sold","c":"商品","s":"The store marks down its summer merchandise at the end of August.","t":"這家店在八月底把夏季商品降價。"},{"w":"retail","p":"n.","d":"the selling of goods to the public in stores","c":"零售","s":"She has worked in retail for ten years, mostly in clothing stores.","t":"她從事零售業十年，大多在服飾店工作。"},{"w":"revenue","p":"n.","d":"the money that a company or government receives","c":"收入；營收","s":"Most of the company's revenue comes from selling phones.","t":"這家公司大部分的營收來自販售手機。"},{"w":"rubbish","p":"n.","d":"things that you throw away because you do not want them","c":"垃圾","s":"Please take the rubbish out before the truck comes.","t":"請在垃圾車來之前把垃圾拿出去。"},{"w":"subsidy","p":"n.","d":"money that a government pays to help reduce the cost of something","c":"補助金","s":"Farmers receive a subsidy from the government to grow rice.","t":"農民種稻可獲得政府的補助金。"},{"w":"transaction","p":"n.","d":"an act of buying or selling something","c":"交易","s":"Every transaction at the bank is recorded on a computer.","t":"銀行的每一筆交易都記錄在電腦上。"},{"w":"violate","p":"v.","d":"to break a law or rule","c":"違反","s":"Drivers who violate the traffic rules will have to pay a fine.","t":"違反交通規則的駕駛必須繳交罰款。"}]},{"unit":11,"theme":"assess – terminal","cards":[{"w":"assess","p":"v.","d":"to judge the quality or amount of something","c":"評估","s":"Teachers use tests to assess how much their students have learned.","t":"老師用測驗來評估學生學了多少。"},{"w":"astonish","p":"v.","d":"to surprise someone very much","c":"使驚訝","s":"The young girl's piano skills never fail to astonish her audience.","t":"那個小女孩的鋼琴技巧總是讓觀眾驚嘆。"},{"w":"commence","p":"v.","d":"to begin","c":"開始","s":"The ceremony will commence at nine o'clock with a short speech.","t":"典禮將於九點以一段簡短致詞開始。"},{"w":"essence","p":"n.","d":"the most important quality of something","c":"本質；精髓","s":"The essence of good teaching is caring about every student.","t":"良好教學的本質是關心每一位學生。"},{"w":"extract","p":"v.","d":"to take something out of something else","c":"提取；拔出","s":"Workers extract oil from deep under the sea.","t":"工人從深海底下開採石油。"},{"w":"fabulous","p":"adj.","d":"very good; wonderful","c":"極好的","s":"We had a fabulous time at the beach and did not want to go home.","t":"我們在海邊玩得非常開心，都不想回家。"},{"w":"haste","p":"n.","d":"great speed in doing something because you have little time","c":"匆忙","s":"In his haste to catch the bus, he left his wallet at home.","t":"他匆忙趕公車，把皮夾忘在家裡。"},{"w":"impulse","p":"n.","d":"a sudden strong wish to do something","c":"衝動","s":"I bought the shoes on impulse and later felt sorry about it.","t":"我一時衝動買了那雙鞋，後來很後悔。"},{"w":"inhibit","p":"v.","d":"to prevent something from growing or happening","c":"抑制；阻礙","s":"Cold weather can inhibit the growth of young plants.","t":"寒冷的天氣會抑制幼苗的生長。"},{"w":"latter","p":"adj.","d":"nearer to the end of a period","c":"後半的；後者的","s":"In the latter part of the year, the weather turns cool.","t":"下半年天氣會轉涼。"},{"w":"molecule","p":"n.","d":"the smallest unit of a substance, made of two or more atoms","c":"分子","s":"A water molecule is made of two hydrogen atoms and one oxygen atom.","t":"一個水分子由兩個氫原子和一個氧原子組成。"},{"w":"ongoing","p":"adj.","d":"continuing to happen","c":"持續進行的","s":"The police said that the search for the missing boy is still ongoing.","t":"警方表示搜尋失蹤男孩的行動仍在持續進行。"},{"w":"precise","p":"adj.","d":"exact and correct","c":"精確的","s":"Can you give me the precise time when the train arrives?","t":"你能告訴我火車到站的精確時間嗎？"},{"w":"proximity","p":"n.","d":"the state of being near something","c":"鄰近；接近","s":"We chose this house because of its proximity to the school.","t":"我們選這棟房子是因為它離學校近。"},{"w":"publicity","p":"n.","d":"attention from newspapers and television","c":"宣傳；關注","s":"The new movie got a lot of publicity before it opened.","t":"這部新電影上映前獲得大量宣傳。"},{"w":"remedy","p":"n.","d":"something that makes an illness or problem better","c":"療法；補救方法","s":"Hot tea with honey is an old remedy for a sore throat.","t":"加蜂蜜的熱茶是治療喉嚨痛的老偏方。"},{"w":"significance","p":"n.","d":"the importance or meaning of something","c":"重要性；意義","s":"Nobody understood the significance of the discovery until years later.","t":"多年後才有人了解這項發現的重要性。"},{"w":"subsequent","p":"adj.","d":"happening after something else","c":"隨後的","s":"The first test was easy, but the subsequent ones were much harder.","t":"第一次考試很簡單，但隨後幾次難多了。"},{"w":"synthetic","p":"adj.","d":"made by people from chemicals, not natural","c":"合成的；人造的","s":"This jacket is made of synthetic material, not real leather.","t":"這件夾克是合成材質做的，不是真皮。"},{"w":"terminal","p":"adj.","d":"(of an illness) that cannot be cured and will cause death","c":"末期的；不治的","s":"The doctors told him that his illness was terminal and he had six months to live.","t":"醫生告訴他病情已到末期，只剩六個月的生命。"}]},{"unit":12,"theme":"acute – virtue","cards":[{"w":"acute","p":"adj.","d":"very serious or severe","c":"嚴重的；急性的","s":"The country is facing an acute shortage of clean drinking water.","t":"該國正面臨嚴重的乾淨飲用水短缺。"},{"w":"aggression","p":"n.","d":"angry or violent behavior toward others","c":"攻擊性；侵略","s":"The dog showed no aggression toward the children and let them pet it.","t":"那隻狗對孩子們沒有表現出攻擊性，還讓他們摸。"},{"w":"biography","p":"n.","d":"the story of a person's life written by someone else","c":"傳記","s":"I am reading a biography of Mozart that tells about his childhood.","t":"我正在讀一本講述莫札特童年的傳記。"},{"w":"boost","p":"v.","d":"to make something increase or become better","c":"提升；增加","s":"A good breakfast can boost your energy for the whole morning.","t":"一頓好的早餐能提升你整個早上的精力。"},{"w":"clap","p":"v.","d":"to hit your hands together to show that you liked something","c":"拍手","s":"The children began to clap when the clown came onto the stage.","t":"小丑上台時，孩子們開始拍手。"},{"w":"classical","p":"adj.","d":"(of music) serious and traditional in style","c":"古典的","s":"She plays classical music by Bach and Mozart on the piano.","t":"她用鋼琴彈奏巴哈和莫札特的古典音樂。"},{"w":"compel","p":"v.","d":"to force someone to do something","c":"強迫","s":"The law will compel all drivers to wear seat belts.","t":"這項法律將強制所有駕駛繫安全帶。"},{"w":"creation","p":"n.","d":"the act of making something new; something that is made","c":"創作；創造","s":"The creation of the new park took three years and a lot of money.","t":"新公園的建造花了三年和大筆經費。"},{"w":"dominance","p":"n.","d":"the state of being more powerful than others","c":"優勢；支配地位","s":"The team continued its dominance by winning its tenth game in a row.","t":"這支球隊以十連勝延續它的優勢。"},{"w":"gorgeous","p":"adj.","d":"very beautiful","c":"極美的；華麗的","s":"The bride looked gorgeous in her long white dress.","t":"新娘穿著白色長禮服，美極了。"},{"w":"inevitable","p":"adj.","d":"certain to happen","c":"不可避免的","s":"If you never study, failing the exam is inevitable.","t":"如果你從不讀書，考試不及格是必然的。"},{"w":"legacy","p":"n.","d":"something that someone leaves behind after they die","c":"遺產；遺留之物","s":"The scientist's greatest legacy was a cure that saved millions of lives.","t":"那位科學家最偉大的遺產是拯救數百萬人性命的療法。"},{"w":"masterpiece","p":"n.","d":"a work of art of the highest quality","c":"傑作","s":"The Mona Lisa is a masterpiece that millions of people travel to see.","t":"《蒙娜麗莎》是數百萬人專程前往觀賞的傑作。"},{"w":"multiple","p":"adj.","d":"many; more than one","c":"多個的；多重的","s":"The driver suffered multiple injuries, including a broken arm and leg.","t":"那名駕駛多處受傷，包括手臂和腿骨折。"},{"w":"narrate","p":"v.","d":"to tell a story","c":"敘述；旁白","s":"A famous actor will narrate the film about wild animals in Africa.","t":"一位知名演員將為這部非洲野生動物影片擔任旁白。"},{"w":"notorious","p":"adj.","d":"famous for something bad","c":"惡名昭彰的","s":"The city is notorious for its terrible traffic jams.","t":"這座城市以嚴重的塞車而惡名昭彰。"},{"w":"overall","p":"adv.","d":"considering everything","c":"整體而言","s":"There were a few small problems, but overall the trip was a success.","t":"雖然有幾個小問題，但整體而言這趟旅行很成功。"},{"w":"partiality","p":"n.","d":"unfair support for one person or side","c":"偏袒；偏愛","s":"A good judge shows no partiality to either side.","t":"好的法官不會偏袒任何一方。"},{"w":"spontaneous","p":"adj.","d":"done suddenly, without planning","c":"自發的；一時興起的","s":"The crowd broke into spontaneous cheers when the singer appeared.","t":"歌手一出現，群眾自發地爆出歡呼。"},{"w":"virtue","p":"n.","d":"a good quality in a person's character","c":"美德","s":"Patience is a virtue that every teacher needs.","t":"耐心是每位老師都需要的美德。"}]},{"unit":13,"theme":"aspect – wax","cards":[{"w":"aspect","p":"n.","d":"one part of a situation or subject","c":"方面","s":"The most difficult aspect of learning English for me is the grammar.","t":"對我來說，學英文最困難的方面是文法。"},{"w":"asset","p":"n.","d":"a useful or valuable person or thing","c":"資產；有價值的人或物","s":"Her ability to speak four languages is a great asset to the company.","t":"她會說四種語言的能力是公司的一大資產。"},{"w":"assignment","p":"n.","d":"a piece of work that someone is given to do","c":"作業；任務","s":"The teacher gave us a writing assignment to finish by Friday.","t":"老師給我們一份週五前要完成的寫作作業。"},{"w":"awareness","p":"n.","d":"knowledge or understanding of a subject or situation","c":"意識；認識","s":"The campaign aims to raise public awareness of the dangers of smoking.","t":"這項活動旨在提高大眾對吸菸危害的認識。"},{"w":"bud","p":"n.","d":"a small part on a plant that grows into a flower or leaf","c":"花苞；芽","s":"In early spring, each branch of the tree is covered with one small bud after another.","t":"早春時，樹的每根枝條上都長滿一個又一個小花苞。"},{"w":"coordinate","p":"v.","d":"to organize people or things so that they work well together","c":"協調","s":"Her job is to coordinate the work of ten different teams.","t":"她的工作是協調十個不同團隊的工作。"},{"w":"credit","p":"n.","d":"praise for something good that you have done","c":"功勞；讚揚","s":"The whole team deserves credit for winning the prize.","t":"整個團隊都應該因獲獎而受到讚揚。"},{"w":"disprove","p":"v.","d":"to show that something is not true","c":"反駁；證明為誤","s":"The scientist did an experiment to disprove the old theory.","t":"那位科學家做了一個實驗來推翻舊理論。"},{"w":"humanitarian","p":"adj.","d":"concerned with helping people who are suffering","c":"人道主義的","s":"The group sent humanitarian aid, such as food and medicine, to the flood victims.","t":"該團體為水災災民送去食物和藥品等人道援助。"},{"w":"hypothesis","p":"n.","d":"an idea that may be true but has not yet been proved","c":"假說；假設","s":"The scientists tested their hypothesis in the lab for two years.","t":"科學家們在實驗室測試他們的假說長達兩年。"},{"w":"informative","p":"adj.","d":"giving useful information","c":"增長知識的；資訊豐富的","s":"The TV program about the ocean was both interesting and informative.","t":"那個關於海洋的電視節目既有趣又增長知識。"},{"w":"optic","p":"adj.","d":"relating to the eyes or to sight","c":"眼睛的；視覺的","s":"The optic nerve carries messages from the eye to the brain.","t":"視神經把訊息從眼睛傳到大腦。"},{"w":"premise","p":"n.","d":"an idea that you accept as true and use as a base for other ideas","c":"前提","s":"The plan is based on the premise that prices will not rise.","t":"這個計畫是以物價不會上漲為前提。"},{"w":"rack","p":"n.","d":"a frame for holding or hanging things","c":"架子","s":"Hang your wet coat on the rack by the door.","t":"把你的濕外套掛在門邊的架子上。"},{"w":"Renaissance","p":"n.","d":"the period in Europe from about 1300 to 1600, when art and learning grew","c":"文藝復興","s":"Leonardo da Vinci was one of the greatest artists of the Renaissance.","t":"達文西是文藝復興時期最偉大的藝術家之一。"},{"w":"spatial","p":"adj.","d":"relating to space and the position of things in it","c":"空間的","s":"Building with blocks helps children develop spatial skills.","t":"堆積木幫助孩子發展空間能力。"},{"w":"specify","p":"v.","d":"to state something clearly and exactly","c":"具體說明；指定","s":"Please specify the size and color you want when you order the shirt.","t":"訂購襯衫時請明確指定你要的尺寸和顏色。"},{"w":"tie","p":"v.","d":"to connect one thing closely with another","c":"使有關聯","s":"Scientists tie the rise in sea levels to the warming of the earth.","t":"科學家把海平面上升與地球暖化連結在一起。"},{"w":"undertake","p":"v.","d":"to agree to do a piece of work","c":"承擔；著手做","s":"The company will undertake a study of the river before building the bridge.","t":"這家公司在建橋前將對河流進行研究。"},{"w":"wax","p":"n.","d":"the soft material that candles are made of","c":"蠟","s":"Hot wax from the candle dripped onto the table.","t":"蠟燭的熱蠟滴到桌上。"}]},{"unit":14,"theme":"addict – team","cards":[{"w":"addict","p":"n.","d":"a person who cannot stop doing or using something harmful","c":"上癮者","s":"The former drug addict now helps young people stay away from drugs.","t":"那位曾經的毒癮者現在幫助年輕人遠離毒品。"},{"w":"archeological","p":"adj.","d":"relating to the study of ancient people and their remains","c":"考古學的","s":"The archeological site contains the ruins of a city three thousand years old.","t":"這個考古遺址有一座三千年前城市的遺跡。"},{"w":"archeology","p":"n.","d":"the study of ancient people through the things they left","c":"考古學","s":"She became interested in archeology after visiting the pyramids.","t":"她參觀金字塔後對考古學產生興趣。"},{"w":"brainstorm","p":"v.","d":"to think of many ideas quickly in a group","c":"腦力激盪","s":"Let's brainstorm some ideas for the school festival before we decide.","t":"做決定前，我們先為校慶腦力激盪一些點子吧。"},{"w":"budget","p":"n.","d":"a plan for how to spend an amount of money","c":"預算","s":"We have a budget of five thousand dollars for the class party.","t":"我們的班級派對預算是五千元。"},{"w":"chaotic","p":"adj.","d":"in a state of complete confusion","c":"混亂的","s":"The streets were chaotic after the power went out and the traffic lights stopped.","t":"停電後紅綠燈失靈，街上一片混亂。"},{"w":"cite","p":"v.","d":"to mention something as an example or proof","c":"引用；舉出","s":"In your essay, you should cite the books you used.","t":"在論文中，你應該引用你參考過的書。"},{"w":"correspond","p":"v.","d":"to be the same as or match something","c":"符合；一致","s":"The numbers on the list do not correspond with the numbers on the boxes.","t":"清單上的號碼和箱子上的號碼不符。"},{"w":"courtyard","p":"n.","d":"an open space surrounded by walls or buildings","c":"庭院；中庭","s":"Children were playing in the courtyard in the middle of the old house.","t":"孩子們在老房子中央的庭院裡玩耍。"},{"w":"estate","p":"n.","d":"a large area of land in the country owned by one person or family","c":"莊園；地產","s":"The rich family owns a large estate with a lake and a forest.","t":"那個富有的家族擁有一座有湖泊和森林的大莊園。"},{"w":"fraud","p":"n.","d":"the crime of cheating someone to get money","c":"詐欺","s":"He went to prison for fraud after stealing money from old people.","t":"他因詐騙老人的錢財而入獄。"},{"w":"hydrogen","p":"n.","d":"the lightest gas, which combines with oxygen to form water","c":"氫","s":"Water is made of hydrogen and oxygen.","t":"水是由氫和氧組成的。"},{"w":"integrity","p":"n.","d":"the quality of being honest and having strong moral principles","c":"正直；誠信","s":"Everyone trusts the judge because she is a woman of great integrity.","t":"大家都信任那位法官，因為她是非常正直的人。"},{"w":"outlook","p":"n.","d":"the way a person thinks about life or the future","c":"觀點；展望","s":"Even after the accident, he kept a positive outlook on life.","t":"即使在事故後，他仍對人生保持樂觀的看法。"},{"w":"parachute","p":"n.","d":"a large piece of cloth that lets a person fall slowly from a plane","c":"降落傘","s":"The pilot jumped out of the plane and opened his parachute.","t":"飛行員跳出飛機並打開降落傘。"},{"w":"prehistoric","p":"adj.","d":"from the time before history was written","c":"史前的","s":"Dinosaurs were prehistoric animals that lived millions of years ago.","t":"恐龍是生活在數百萬年前的史前動物。"},{"w":"proponent","p":"n.","d":"a person who supports an idea or plan","c":"支持者；倡導者","s":"She is a strong proponent of free school lunches for all children.","t":"她大力支持為所有孩童提供免費營養午餐。"},{"w":"refine","p":"v.","d":"to improve something by making small changes","c":"改進；精煉","s":"The engineers worked for months to refine the design of the new phone.","t":"工程師花了數月改進新手機的設計。"},{"w":"restrict","p":"v.","d":"to limit the size, amount, or range of something","c":"限制","s":"The school decided to restrict the use of cellphones during class.","t":"學校決定限制上課時使用手機。"},{"w":"team","p":"n.","d":"a group of people who work or play together","c":"團隊；隊伍","s":"A team of doctors worked all night to save the child's life.","t":"一組醫生徹夜搶救那個孩子的性命。"}]},{"unit":15,"theme":"aggregate – viral","cards":[{"w":"aggregate","p":"adj.","d":"made by adding together all the amounts","c":"總計的","s":"The aggregate score of the two games was five to three.","t":"兩場比賽的總比分是五比三。"},{"w":"antibiotic","p":"n.","d":"a medicine that kills bacteria and cures infections","c":"抗生素","s":"The doctor gave her an antibiotic to treat the infection in her ear.","t":"醫生給她開了抗生素治療耳朵的感染。"},{"w":"circuit","p":"n.","d":"the complete path that electricity flows around","c":"電路","s":"When you turn on the switch, you close the circuit and the light comes on.","t":"打開開關時電路接通，燈就亮了。"},{"w":"complement","p":"v.","d":"to make something better by adding to it","c":"補足；與…相配","s":"The red wine will complement the taste of the steak perfectly.","t":"紅酒和牛排的味道會搭配得恰到好處。"},{"w":"compress","p":"v.","d":"to press something into a smaller space","c":"壓縮","s":"You can compress the file to make it small enough to send by e-mail.","t":"你可以壓縮檔案，讓它小到能用電子郵件寄出。"},{"w":"database","p":"n.","d":"a large collection of information stored in a computer","c":"資料庫","s":"The library keeps the names of all its books in a database.","t":"圖書館把所有書名存放在資料庫裡。"},{"w":"equivalent","p":"n.","d":"something that has the same value or meaning as another thing","c":"相等物；對應物","s":"There is no exact English equivalent for this Chinese word.","t":"這個中文字沒有完全對應的英文字。"},{"w":"immune","p":"adj.","d":"not able to be harmed by a disease","c":"免疫的","s":"After you have had the disease once, you are usually immune to it.","t":"得過一次這種病之後，你通常就對它免疫了。"},{"w":"input","p":"n.","d":"ideas or information that you give to help a project","c":"意見；投入","s":"We would like your input before we make a final decision.","t":"在做最後決定前，我們想聽聽你的意見。"},{"w":"intimate","p":"adj.","d":"very close and personal","c":"親密的","s":"She shared the secret only with a few intimate friends.","t":"她只把這個秘密告訴幾位親密的朋友。"},{"w":"magnet","p":"n.","d":"a piece of metal that pulls iron toward it","c":"磁鐵","s":"I used a magnet to pick up the pins that fell on the floor.","t":"我用磁鐵把掉在地上的大頭針吸起來。"},{"w":"metabolism","p":"n.","d":"the process by which the body turns food into energy","c":"新陳代謝","s":"Exercise speeds up your metabolism, so you burn more energy.","t":"運動會加速你的新陳代謝，讓你燃燒更多能量。"},{"w":"microchip","p":"n.","d":"a very small part that makes a computer or phone work","c":"微晶片","s":"The vet put a microchip under the dog's skin so it could be found if lost.","t":"獸醫在狗的皮下植入微晶片，這樣走失時能找回來。"},{"w":"phase","p":"n.","d":"one part of a process","c":"階段","s":"The first phase of the building project will take six months.","t":"建築工程的第一階段將需要六個月。"},{"w":"pinch","p":"v.","d":"to press something tightly between your finger and thumb","c":"捏","s":"Don't pinch your little sister's arm; it hurts her.","t":"別捏你妹妹的手臂，她會痛。"},{"w":"prevalent","p":"adj.","d":"common in a place or at a time","c":"普遍的；盛行的","s":"Colds are most prevalent in winter, when people stay indoors.","t":"感冒在人們待在室內的冬天最為普遍。"},{"w":"quantum","p":"n.","d":"the smallest amount of energy that can exist","c":"量子","s":"He is studying quantum physics, the science of the smallest things.","t":"他正在研究量子物理，也就是研究最微小事物的科學。"},{"w":"ratio","p":"n.","d":"the relationship between two amounts","c":"比例","s":"The ratio of teachers to students in this school is one to twenty.","t":"這所學校的師生比是一比二十。"},{"w":"spiral","p":"n.","d":"a shape that curves around and around a central point","c":"螺旋","s":"The stairs go up in a spiral to the top of the tower.","t":"樓梯以螺旋狀通往塔頂。"},{"w":"viral","p":"adj.","d":"caused by a virus; spreading very quickly on the Internet","c":"病毒的；網路爆紅的","s":"The funny cat video went viral and was watched ten million times.","t":"那支好笑的貓咪影片在網路上爆紅，被觀看一千萬次。"}]},{"unit":16,"theme":"acid – straightforward","cards":[{"w":"acid","p":"n.","d":"a chemical substance with a sour taste that can burn things","c":"酸","s":"The acid in lemon juice can clean the black marks off a pot.","t":"檸檬汁裡的酸可以清除鍋子上的黑漬。"},{"w":"administration","p":"n.","d":"the government of a country at a certain time; the work of managing","c":"政府；行政管理","s":"The new administration promised to build more schools and hospitals.","t":"新政府承諾興建更多學校和醫院。"},{"w":"administrative","p":"adj.","d":"relating to the work of managing an organization","c":"行政的","s":"She does administrative work, such as answering letters and keeping records.","t":"她做行政工作，例如回覆信件和保管紀錄。"},{"w":"biotechnology","p":"n.","d":"the use of living things to make useful products","c":"生物科技","s":"Scientists use biotechnology to grow crops that need less water.","t":"科學家利用生物科技種出需水量較少的作物。"},{"w":"cholesterol","p":"n.","d":"a fatty substance in the blood that can cause heart disease","c":"膽固醇","s":"Eating too many eggs and too much meat can raise your cholesterol.","t":"吃太多蛋和肉會使你的膽固醇升高。"},{"w":"coalition","p":"n.","d":"a group of people or parties that work together","c":"聯盟","s":"Three small parties formed a coalition to win the election.","t":"三個小黨組成聯盟以贏得選舉。"},{"w":"deceptive","p":"adj.","d":"making you believe something that is not true","c":"騙人的；造成假象的","s":"The box looks large, but its size is deceptive; there is little inside.","t":"盒子看起來很大，但大小會騙人，裡面沒什麼東西。"},{"w":"diabetes","p":"n.","d":"a disease in which there is too much sugar in the blood","c":"糖尿病","s":"People with diabetes must be careful about how much sugar they eat.","t":"糖尿病患者必須注意糖分的攝取量。"},{"w":"eliminate","p":"v.","d":"to remove something completely","c":"消除；淘汰","s":"The new machine will eliminate the need to wash dishes by hand.","t":"這台新機器將免去用手洗碗的需要。"},{"w":"erosion","p":"n.","d":"the slow wearing away of land by wind or water","c":"侵蝕","s":"Planting trees on the hill helps prevent soil erosion.","t":"在山坡上種樹有助於防止土壤侵蝕。"},{"w":"ethics","p":"n.","d":"ideas about what is right and wrong","c":"倫理；道德規範","s":"Doctors must follow a strict code of ethics when treating patients.","t":"醫生治療病人時必須遵守嚴格的倫理規範。"},{"w":"explicit","p":"adj.","d":"clear and exact","c":"明確的；清楚的","s":"The teacher gave explicit instructions, so nobody was confused.","t":"老師給了明確的指示，所以沒有人感到困惑。"},{"w":"framework","p":"n.","d":"a set of ideas or rules used as a base for something","c":"架構；框架","s":"The report gives a framework for improving schools over ten years.","t":"這份報告提出了十年內改善學校的架構。"},{"w":"manufacture","p":"v.","d":"to make things in large numbers in a factory","c":"製造","s":"The company plans to manufacture electric cars in its new factory.","t":"這家公司計畫在新工廠製造電動車。"},{"w":"mechanism","p":"n.","d":"a set of moving parts that work together in a machine","c":"機械裝置；機制","s":"The lock has a simple mechanism that anyone can repair.","t":"這個鎖的機械裝置很簡單，任何人都能修。"},{"w":"minimize","p":"v.","d":"to make something as small as possible","c":"使減到最少","s":"Wash your hands often to minimize the risk of getting sick.","t":"經常洗手，把生病的風險降到最低。"},{"w":"nectar","p":"n.","d":"the sweet liquid that bees collect from flowers","c":"花蜜","s":"Bees fly from flower to flower to collect nectar.","t":"蜜蜂在花朵間飛來飛去採集花蜜。"},{"w":"notion","p":"n.","d":"an idea or belief","c":"觀念；想法","s":"He has the strange notion that cold water is bad for the stomach.","t":"他有個奇怪的觀念，認為冷水對胃不好。"},{"w":"regime","p":"n.","d":"a government, especially one that was not fairly elected","c":"政權","s":"Under the old regime, people could not speak freely.","t":"在舊政權統治下，人民不能自由發言。"},{"w":"straightforward","p":"adj.","d":"easy to understand or do","c":"簡單明瞭的；直率的","s":"The directions were straightforward, and we found the house easily.","t":"路線指示簡單明瞭，我們很容易就找到那棟房子。"}]},{"unit":17,"theme":"bankrupt – whereby","cards":[{"w":"bankrupt","p":"adj.","d":"not having enough money to pay what you owe","c":"破產的","s":"The company went bankrupt after losing millions of dollars.","t":"這家公司虧損數百萬元後破產了。"},{"w":"conform","p":"v.","d":"to obey a rule or behave like everyone else","c":"遵守；順從","s":"All students must conform to the school's dress code.","t":"所有學生都必須遵守學校的服裝規定。"},{"w":"employ","p":"v.","d":"to pay someone to work for you","c":"雇用","s":"The new factory will employ five hundred workers.","t":"新工廠將雇用五百名工人。"},{"w":"expel","p":"v.","d":"to force someone to leave a school or country","c":"開除；驅逐","s":"The school may expel students who cheat on exams.","t":"學校可能開除考試作弊的學生。"},{"w":"extension","p":"n.","d":"extra time allowed for something","c":"延期；延長","s":"I asked my teacher for a two-day extension on my report.","t":"我請老師讓我的報告延後兩天交。"},{"w":"forthcoming","p":"adj.","d":"happening soon","c":"即將到來的","s":"Everyone is talking about the forthcoming election next month.","t":"大家都在談論下個月即將到來的選舉。"},{"w":"furnish","p":"v.","d":"to put furniture in a room or house","c":"為…配置家具","s":"They plan to furnish the new apartment with a sofa, a bed, and a table.","t":"他們打算為新公寓添購沙發、床和桌子。"},{"w":"hygiene","p":"n.","d":"the practice of keeping yourself and things clean","c":"衛生","s":"Good hygiene, such as washing your hands, prevents many diseases.","t":"良好的衛生習慣，例如洗手，可預防許多疾病。"},{"w":"hygienic","p":"adj.","d":"clean and free from germs","c":"衛生的","s":"It is not hygienic to eat without washing your hands.","t":"沒洗手就吃東西不衛生。"},{"w":"landlord","p":"n.","d":"a person who owns a house and rents it to others","c":"房東","s":"Our landlord raised the rent by two thousand dollars this year.","t":"我們的房東今年把房租調漲了兩千元。"},{"w":"lease","p":"v.","d":"to use or let someone use a building or car for a fixed time in return for money","c":"租用；出租","s":"The company decided to lease an office downtown for three years.","t":"這家公司決定在市中心租用辦公室三年。"},{"w":"mandatory","p":"adj.","d":"required by a rule or law","c":"強制的；義務的","s":"Wearing a helmet is mandatory for all motorcycle riders.","t":"所有機車騎士都必須戴安全帽。"},{"w":"mend","p":"v.","d":"to repair something that is torn or broken","c":"修補","s":"Grandma used a needle and thread to mend the hole in my sock.","t":"奶奶用針線修補我襪子上的破洞。"},{"w":"mortgage","p":"n.","d":"money that you borrow from a bank to buy a house","c":"房屋貸款","s":"They took out a thirty-year mortgage to buy their first home.","t":"他們辦了三十年的房貸來買第一棟房子。"},{"w":"personnel","p":"n.","d":"all the people who work in an organization","c":"全體人員；員工","s":"Only hospital personnel are allowed to enter this room.","t":"只有醫院人員才能進入這個房間。"},{"w":"plumbing","p":"n.","d":"the system of water pipes in a building","c":"水管設備","s":"The plumbing in the old house leaks, so the floor is always wet.","t":"老房子的水管會漏水，所以地板總是濕的。"},{"w":"quote","p":"n.","d":"words that someone else said or wrote, repeated exactly","c":"引言；引述","s":"She began her speech with a quote from a famous poet.","t":"她以一位著名詩人的名言作為演講的開場。"},{"w":"tenant","p":"n.","d":"a person who pays rent to live in a house or room","c":"房客","s":"The tenant on the second floor pays his rent on the first of every month.","t":"二樓的房客每月一號繳房租。"},{"w":"utility","p":"n.","d":"a service such as water, gas, or electricity that the public uses","c":"公用事業（水、電、瓦斯）","s":"The rent does not include any utility, so you must pay for water and power.","t":"房租不包含任何水電瓦斯費，所以你得另外付水電費。"},{"w":"whereby","p":"adv.","d":"by which","c":"藉此；憑此","s":"The school has a system whereby older students help younger ones with reading.","t":"學校有一套制度，藉此讓高年級學生幫助低年級學生閱讀。"}]},{"unit":18,"theme":"adapt – transplant","cards":[{"w":"adapt","p":"v.","d":"to change in order to fit a new situation","c":"適應","s":"It took the children a few months to adapt to their new school.","t":"孩子們花了幾個月才適應新學校。"},{"w":"biological","p":"adj.","d":"relating to living things; related by birth","c":"生物的；親生的","s":"She met her biological mother for the first time at the age of twenty.","t":"她二十歲時第一次見到親生母親。"},{"w":"cellular","p":"adj.","d":"relating to the cells of living things","c":"細胞的","s":"The disease causes damage at the cellular level, deep inside the body.","t":"這種疾病在細胞層次上造成損害，深入體內。"},{"w":"dynamic","p":"adj.","d":"full of energy and new ideas","c":"有活力的","s":"The dynamic young teacher made every class exciting.","t":"那位充滿活力的年輕老師讓每堂課都很精彩。"},{"w":"fantasy","p":"n.","d":"something pleasant that you imagine but that is not real","c":"幻想","s":"His fantasy is to fly to the moon in his own rocket.","t":"他的幻想是搭自己的火箭飛到月球。"},{"w":"heredity","p":"n.","d":"the passing of qualities from parents to children","c":"遺傳","s":"Eye color is decided by heredity, not by what you eat.","t":"眼睛的顏色由遺傳決定，而不是你吃的東西。"},{"w":"internal","p":"adj.","d":"inside the body or inside a place","c":"內部的；體內的","s":"He had no cuts, but the doctor found internal injuries.","t":"他身上沒有傷口，但醫生發現有內傷。"},{"w":"minimal","p":"adj.","d":"very small in amount","c":"極小的；最低限度的","s":"The storm caused only minimal damage; just a few leaves fell.","t":"這場暴風雨只造成極小的損害，僅有幾片葉子掉落。"},{"w":"pioneer","p":"n.","d":"one of the first people to do something new","c":"先驅；拓荒者","s":"She was a pioneer in heart surgery and trained hundreds of doctors.","t":"她是心臟外科的先驅，培訓了數百名醫生。"},{"w":"prescribe","p":"v.","d":"(of a doctor) to say what medicine a patient should take","c":"開（藥方）","s":"The doctor will prescribe some medicine for your cough.","t":"醫生會為你的咳嗽開一些藥。"},{"w":"respective","p":"adj.","d":"belonging to each one separately","c":"各自的","s":"After the meeting, the teachers returned to their respective classrooms.","t":"會議後，老師們回到各自的教室。"},{"w":"rigid","p":"adj.","d":"stiff and hard to bend; not able to be changed","c":"堅硬的；嚴格的","s":"The tent is held up by a rigid metal frame.","t":"這頂帳篷由堅硬的金屬骨架支撐。"},{"w":"sequence","p":"n.","d":"the order in which things happen or are arranged","c":"順序；一連串","s":"Put the pictures in the correct sequence to tell the story.","t":"把圖片按正確順序排列來說故事。"},{"w":"similar","p":"adj.","d":"almost the same","c":"相似的","s":"The two sisters have similar voices, so I often mix them up on the phone.","t":"這對姊妹的聲音很像，所以我在電話裡常常搞混。"},{"w":"substitute","p":"v.","d":"to use one thing in place of another","c":"用…代替","s":"You can substitute honey for sugar in this cake recipe.","t":"在這份蛋糕食譜中，你可以用蜂蜜代替糖。"},{"w":"surgeon","p":"n.","d":"a doctor who performs operations","c":"外科醫生","s":"The surgeon operated on the boy's heart for six hours.","t":"外科醫生為那個男孩的心臟動了六小時的手術。"},{"w":"therapy","p":"n.","d":"treatment for an illness or injury","c":"治療；療法","s":"After the accident, he needed months of physical therapy to walk again.","t":"事故後，他需要數月的物理治療才能再次行走。"},{"w":"transfer","p":"v.","d":"to move from one place to another","c":"轉移；調動","s":"The company will transfer him to its office in Tokyo next year.","t":"公司明年將把他調到東京辦事處。"},{"w":"transition","p":"n.","d":"the process of changing from one state to another","c":"過渡；轉變","s":"The transition from elementary school to junior high can be difficult.","t":"從小學升上國中的過渡期可能很辛苦。"},{"w":"transplant","p":"n.","d":"an operation in which an organ is moved into another person's body","c":"移植","s":"He needs a heart transplant to stay alive.","t":"他需要心臟移植才能活下去。"}]},{"unit":19,"theme":"astrology – technique","cards":[{"w":"astrology","p":"n.","d":"the study of how the stars and planets are believed to affect people's lives","c":"占星術","s":"She believes in astrology and reads about her star sign every morning.","t":"她相信占星術，每天早上都看自己的星座運勢。"},{"w":"couple","p":"n.","d":"two people who are married or in a relationship","c":"一對；夫妻","s":"The young couple got married last spring and moved to Taipei.","t":"那對年輕夫妻去年春天結婚後搬到台北。"},{"w":"deviate","p":"v.","d":"to do something different from what is usual or planned","c":"偏離","s":"The pilot had to deviate from the usual route because of the storm.","t":"飛行員因暴風雨不得不偏離平常的航線。"},{"w":"differentiate","p":"v.","d":"to see or show the difference between things","c":"區分；辨別","s":"Young babies cannot differentiate between day and night.","t":"小嬰兒無法分辨白天和黑夜。"},{"w":"disrupt","p":"v.","d":"to stop something from continuing in the normal way","c":"擾亂；中斷","s":"Heavy snow may disrupt train service across the country.","t":"大雪可能擾亂全國的火車營運。"},{"w":"equation","p":"n.","d":"a statement in math that two amounts are equal","c":"方程式；等式","s":"The teacher wrote the equation \"2x + 3 = 7\" on the board.","t":"老師在黑板上寫下「2x + 3 = 7」這個方程式。"},{"w":"err","p":"v.","d":"to make a mistake","c":"犯錯","s":"It is human to err, so don't be too hard on yourself.","t":"人都會犯錯，所以別對自己太苛刻。"},{"w":"erroneous","p":"adj.","d":"not correct","c":"錯誤的","s":"The newspaper apologized for printing erroneous information about the accident.","t":"報社為刊登有關事故的錯誤資訊而道歉。"},{"w":"frantic","p":"adj.","d":"very worried and unable to stay calm","c":"慌亂的；發狂似的","s":"The frantic mother ran through the store calling her lost child's name.","t":"那位慌亂的母親在店裡奔跑，呼喊走失孩子的名字。"},{"w":"inadvertent","p":"adj.","d":"not done on purpose","c":"無心的；非故意的","s":"It was an inadvertent mistake; I did not mean to delete your file.","t":"那是無心之過，我不是故意刪除你的檔案。"},{"w":"improvise","p":"v.","d":"to make or do something without preparing first","c":"即興創作；臨時湊合","s":"The actor forgot his lines and had to improvise on stage.","t":"那位演員忘了台詞，只好在台上即興發揮。"},{"w":"latitude","p":"n.","d":"the distance of a place north or south of the equator","c":"緯度","s":"Taipei lies at a latitude of about twenty-five degrees north.","t":"台北位於大約北緯二十五度。"},{"w":"mariner","p":"n.","d":"a sailor","c":"水手；航海者","s":"The old mariner had sailed every ocean in the world.","t":"那位老水手航行過世界上每一片海洋。"},{"w":"multitude","p":"n.","d":"a very large number of people or things","c":"大量；許多","s":"A multitude of stars filled the clear night sky.","t":"無數的星星佈滿晴朗的夜空。"},{"w":"nuisance","p":"n.","d":"a person or thing that annoys you","c":"討厭的人或事物","s":"The flies are a real nuisance when we eat outside in summer.","t":"夏天在戶外吃飯時，蒼蠅真是討厭。"},{"w":"permanence","p":"n.","d":"the state of lasting for a long time or forever","c":"永久；持久","s":"After moving ten times, the family wanted some permanence in their lives.","t":"搬了十次家後，這家人希望生活能安定長久一些。"},{"w":"revolve","p":"v.","d":"to move around something in a circle","c":"旋轉；環繞","s":"The earth and the other planets revolve around the sun.","t":"地球和其他行星繞著太陽運轉。"},{"w":"soothe","p":"v.","d":"to make someone feel calmer or less in pain","c":"安撫；緩和","s":"The mother sang softly to soothe her crying baby.","t":"母親輕聲歌唱安撫哭鬧的寶寶。"},{"w":"stranded","p":"adj.","d":"unable to leave a place","c":"受困的；滯留的","s":"Hundreds of travelers were stranded at the airport because of the snow.","t":"數百名旅客因大雪滯留在機場。"},{"w":"technique","p":"n.","d":"a special way of doing something","c":"技巧；技術","s":"The swimming coach taught us a new technique for breathing in the water.","t":"游泳教練教我們一種在水中換氣的新技巧。"}]},{"unit":20,"theme":"absurd – vanity","cards":[{"w":"absurd","p":"adj.","d":"completely silly or unreasonable","c":"荒謬的","s":"It is absurd to pay a thousand dollars for a cup of coffee.","t":"花一千元買一杯咖啡太荒謬了。"},{"w":"aristocracy","p":"n.","d":"the highest social class, made up of people with titles and land","c":"貴族階級","s":"In the past, the aristocracy owned most of the land in the country.","t":"過去貴族階級擁有全國大部分的土地。"},{"w":"aristocrat","p":"n.","d":"a person who belongs to the highest social class","c":"貴族","s":"The aristocrat lived in a huge house with fifty servants.","t":"那位貴族住在有五十名僕人的大宅裡。"},{"w":"attire","p":"n.","d":"clothes, especially formal ones","c":"服裝","s":"Formal attire, such as a suit or a long dress, is required at the dinner.","t":"晚宴需穿著正式服裝，例如西裝或長禮服。"},{"w":"craze","p":"n.","d":"something that is very popular for a short time","c":"熱潮；狂熱","s":"The game became a craze among teenagers last summer.","t":"那款遊戲去年夏天在青少年間掀起熱潮。"},{"w":"denote","p":"v.","d":"to be a sign of something; to mean","c":"表示；代表","s":"On this map, blue lines denote rivers.","t":"在這張地圖上，藍線代表河流。"},{"w":"enlarge","p":"v.","d":"to make something bigger","c":"放大；擴大","s":"I want to enlarge this photo and hang it on the wall.","t":"我想把這張照片放大掛在牆上。"},{"w":"excess","p":"n.","d":"an amount that is more than what is needed","c":"過量；過剩","s":"An excess of sugar in your diet can harm your health.","t":"飲食中糖分過量會損害你的健康。"},{"w":"feminine","p":"adj.","d":"having qualities that are thought to be typical of women","c":"女性的；有女人味的","s":"The room was painted in soft, feminine colors like pink and light purple.","t":"房間漆成粉紅和淡紫等柔和的女性化色彩。"},{"w":"hierarchy","p":"n.","d":"a system in which people are arranged by rank","c":"階層；等級制度","s":"In the army hierarchy, a general is far above a soldier.","t":"在軍隊的階層中，將軍遠高於士兵。"},{"w":"pad","p":"n.","d":"a thick piece of soft material used for protection or comfort","c":"墊子；護墊","s":"Skaters wear a pad on each knee to protect them when they fall.","t":"溜冰的人在每個膝蓋上戴護墊，跌倒時可以保護。"},{"w":"partner","p":"n.","d":"a person you do an activity or business with","c":"夥伴；搭檔","s":"Each student must work with a partner on this project.","t":"每位學生都必須和一位夥伴合作完成這個專題。"},{"w":"predominant","p":"adj.","d":"more important or common than others","c":"主要的；佔優勢的","s":"Green is the predominant color in the painting of the forest.","t":"在這幅森林畫中，綠色是主要的顏色。"},{"w":"protocol","p":"n.","d":"the rules for correct behavior on official occasions","c":"禮節；規範","s":"According to protocol, the president enters the room last.","t":"依照禮節，總統最後進入會場。"},{"w":"reputable","p":"adj.","d":"known to be good and honest","c":"聲譽良好的","s":"Buy your computer from a reputable store, not from a stranger online.","t":"向聲譽良好的商店買電腦，不要向網路上的陌生人買。"},{"w":"signify","p":"v.","d":"to be a sign of something","c":"表示；意味著","s":"Dark clouds often signify that a storm is coming.","t":"烏雲常常表示暴風雨即將來臨。"},{"w":"strap","p":"n.","d":"a narrow piece of leather or cloth used to hold or carry something","c":"帶子","s":"The strap of my bag broke, so I had to carry it in my arms.","t":"我的包包帶子斷了，所以只好抱著它。"},{"w":"style","p":"n.","d":"a particular way of doing or designing something","c":"風格；樣式","s":"I like the style of this dress, but I want it in a different color.","t":"我喜歡這件洋裝的樣式，但想要別的顏色。"},{"w":"tangle","p":"n.","d":"a mass of hair or string twisted together in an untidy way","c":"糾結；亂成一團","s":"Her long hair was in a tangle after she rode in the open car.","t":"坐完敞篷車後，她的長髮亂成一團。"},{"w":"vanity","p":"n.","d":"too much pride in your looks or abilities","c":"虛榮；自負","s":"His vanity makes him look in every mirror he passes.","t":"他的虛榮心讓他經過每面鏡子都要照一下。"}]},{"unit":21,"theme":"ashore – vigorous","cards":[{"w":"ashore","p":"adv.","d":"onto land from the sea or a river","c":"上岸；在岸上","s":"The sailors swam ashore after their boat sank.","t":"船沉沒後，水手們游上岸。"},{"w":"contradict","p":"v.","d":"to say the opposite of what someone else has said","c":"反駁；與…矛盾","s":"The two reports contradict each other, so one of them must be wrong.","t":"這兩份報告互相矛盾，所以其中一份一定有錯。"},{"w":"counterpart","p":"n.","d":"a person or thing with the same job or purpose in a different place","c":"對應的人或物","s":"The Taiwanese minister met his Japanese counterpart in Tokyo.","t":"台灣的部長在東京會見日本的對等官員。"},{"w":"devoid","p":"adj.","d":"completely without something","c":"缺乏的；毫無的","s":"The desert is almost devoid of water and plants.","t":"沙漠幾乎沒有水和植物。"},{"w":"diverge","p":"v.","d":"to separate and go in different directions","c":"分岔；分歧","s":"The two roads diverge just after the bridge, one going north and one going east.","t":"這兩條路一過橋就分岔，一條往北，一條往東。"},{"w":"embryo","p":"n.","d":"a human or animal in the earliest stage before birth","c":"胚胎","s":"The embryo of a chicken grows inside the egg for twenty-one days.","t":"小雞的胚胎在蛋裡生長二十一天。"},{"w":"finally","p":"adv.","d":"after a long time","c":"終於；最後","s":"After waiting for two hours, we finally got on the bus.","t":"等了兩小時後，我們終於上了公車。"},{"w":"gazette","p":"n.","d":"a newspaper","c":"公報；報紙","s":"The story was printed on the front page of the local gazette.","t":"這則報導刊登在地方報的頭版。"},{"w":"homogeneous","p":"adj.","d":"made up of things or people that are all the same","c":"同質的；相同種類的","s":"The class is homogeneous: all the students are the same age and level.","t":"這個班是同質的：所有學生年齡和程度都相同。"},{"w":"individual","p":"n.","d":"a single person, separate from a group","c":"個人","s":"Every individual has the right to speak freely.","t":"每個人都有自由發言的權利。"},{"w":"major","p":"adj.","d":"very large or important","c":"主要的；重大的","s":"Traffic is a major problem in most big cities.","t":"交通是大多數大城市的重大問題。"},{"w":"obstruct","p":"v.","d":"to block a road or path","c":"阻塞；妨礙","s":"Please move your car so that it does not obstruct the entrance.","t":"請把你的車移開，以免擋住入口。"},{"w":"plunge","p":"v.","d":"to jump or fall suddenly into something","c":"跳入；猛跌","s":"On hot days, the children love to plunge into the cool river.","t":"天氣熱時，孩子們喜歡跳進清涼的河裡。"},{"w":"prolong","p":"v.","d":"to make something last longer","c":"延長","s":"Regular exercise can prolong your life by several years.","t":"規律運動可以延長你數年的壽命。"},{"w":"publicize","p":"v.","d":"to give information about something to the public","c":"宣傳；公布","s":"The school will publicize the concert with posters and online ads.","t":"學校將用海報和網路廣告宣傳這場音樂會。"},{"w":"surplus","p":"n.","d":"an amount that is more than what is needed","c":"過剩；盈餘","s":"The farmers sold their surplus of rice to other countries.","t":"農民把過剩的稻米賣到其他國家。"},{"w":"survive","p":"v.","d":"to continue to live after a dangerous event","c":"存活；倖存","s":"Only three passengers managed to survive the plane crash.","t":"只有三名乘客在墜機中倖存。"},{"w":"theorize","p":"v.","d":"to suggest ideas to explain something","c":"推論；建立理論","s":"Scientists theorize that the moon was once part of the earth.","t":"科學家推論月球曾經是地球的一部分。"},{"w":"verify","p":"v.","d":"to check that something is true","c":"核實；證實","s":"The bank called to verify my address and phone number.","t":"銀行打電話來核實我的地址和電話號碼。"},{"w":"vigorous","p":"adj.","d":"very active and full of energy","c":"精力充沛的；劇烈的","s":"After twenty minutes of vigorous exercise, we were all out of breath.","t":"劇烈運動二十分鐘後，我們全都氣喘吁吁。"}]},{"unit":22,"theme":"altar – text","cards":[{"w":"altar","p":"n.","d":"a table used in religious ceremonies","c":"祭壇","s":"The bride and groom stood before the altar in the church.","t":"新娘和新郎站在教堂的祭壇前。"},{"w":"arthritis","p":"n.","d":"a disease that causes pain in the joints of the body","c":"關節炎","s":"My grandmother's arthritis makes it painful for her to bend her fingers.","t":"我祖母的關節炎讓她彎手指時很痛。"},{"w":"botany","p":"n.","d":"the study of plants","c":"植物學","s":"She studies botany and can name every flower in the garden.","t":"她研讀植物學，能說出花園裡每種花的名字。"},{"w":"credible","p":"adj.","d":"able to be believed or trusted","c":"可信的","s":"The police believed the witness because her story was credible.","t":"警方相信那位證人，因為她的說法可信。"},{"w":"deceased","p":"adj.","d":"dead","c":"已故的","s":"The house once belonged to her deceased grandfather.","t":"這棟房子曾經屬於她已故的祖父。"},{"w":"deception","p":"n.","d":"the act of making someone believe something that is not true","c":"欺騙","s":"He got the old man's money through lies and deception.","t":"他靠謊言和欺騙取得那位老人的錢。"},{"w":"document","p":"n.","d":"an official paper that gives information","c":"文件","s":"Please sign this document and return it to the office.","t":"請在這份文件上簽名並交回辦公室。"},{"w":"dung","p":"n.","d":"solid waste from large animals","c":"糞便","s":"Farmers spread cow dung on the fields to help the crops grow.","t":"農民把牛糞撒在田裡幫助作物生長。"},{"w":"dusk","p":"n.","d":"the time just before night when it is not yet completely dark","c":"黃昏","s":"The street lights come on at dusk, just after the sun goes down.","t":"黃昏時分，太陽剛下山，路燈就亮了。"},{"w":"gratify","p":"v.","d":"to please someone","c":"使滿足；使高興","s":"It would gratify the teacher to see all her students pass the exam.","t":"看到所有學生通過考試會讓老師很欣慰。"},{"w":"hone","p":"v.","d":"to improve a skill over time","c":"磨練","s":"She joined the debate club to hone her speaking skills.","t":"她加入辯論社來磨練口語能力。"},{"w":"interpret","p":"v.","d":"to explain the meaning of something","c":"解讀；詮釋","s":"Different readers interpret the same poem in different ways.","t":"不同的讀者對同一首詩有不同的解讀。"},{"w":"motive","p":"n.","d":"the reason for doing something","c":"動機","s":"The police still do not know the motive for the crime.","t":"警方仍不清楚犯案的動機。"},{"w":"pneumonia","p":"n.","d":"a serious illness of the lungs","c":"肺炎","s":"The old man caught pneumonia and spent two weeks in the hospital.","t":"那位老人得了肺炎，在醫院住了兩週。"},{"w":"psychic","p":"adj.","d":"having strange powers of the mind, such as knowing the future","c":"通靈的；有特異功能的","s":"She claims to have psychic powers and says she can read people's thoughts.","t":"她自稱有特異功能，說能讀懂別人的想法。"},{"w":"psychotic","p":"adj.","d":"having a serious mental illness that makes a person lose touch with reality","c":"精神病的","s":"The psychotic patient believed that he was a king from another planet.","t":"那位精神病患相信自己是來自另一個星球的國王。"},{"w":"scope","p":"n.","d":"the range of things that a subject or activity deals with","c":"範圍","s":"This question is outside the scope of today's lesson.","t":"這個問題超出今天課程的範圍。"},{"w":"sinister","p":"adj.","d":"seeming evil or dangerous","c":"陰險的；不祥的","s":"There was something sinister about the man's cold smile.","t":"那個男人冰冷的笑容裡有種陰險的感覺。"},{"w":"strife","p":"n.","d":"angry disagreement or fighting between people","c":"衝突；紛爭","s":"Years of strife between the two families finally ended with a wedding.","t":"兩個家族多年的紛爭終於以一場婚禮畫下句點。"},{"w":"text","p":"n.","d":"the written words in a book or on a page","c":"文字；文本","s":"The book has many pictures and very little text.","t":"這本書圖片很多，文字很少。"}]},{"unit":23,"theme":"artery – susceptible","cards":[{"w":"artery","p":"n.","d":"a tube that carries blood from the heart to the rest of the body","c":"動脈","s":"A blocked artery can stop blood from reaching the heart.","t":"動脈阻塞會使血液無法到達心臟。"},{"w":"deterioration","p":"n.","d":"the process of becoming worse","c":"惡化","s":"The doctor noticed a deterioration in the old woman's memory.","t":"醫生注意到那位老婦人的記憶力惡化。"},{"w":"elusive","p":"adj.","d":"difficult to find or catch","c":"難以捉摸的；難找到的","s":"The elusive thief escaped from the police three times in one month.","t":"那個難以捉拿的小偷一個月內三度逃過警方追捕。"},{"w":"ensure","p":"v.","d":"to make certain that something happens","c":"確保","s":"Please check the door twice to ensure that it is locked.","t":"請檢查門兩次，確保門鎖好了。"},{"w":"induce","p":"v.","d":"to cause something to happen","c":"引起；誘使","s":"Warm milk can help induce sleep in young children.","t":"溫牛奶有助於讓幼兒入睡。"},{"w":"inseparable","p":"adj.","d":"not able to be separated","c":"形影不離的；不可分的","s":"The two friends have been inseparable since their first day at school.","t":"這兩個朋友從上學第一天起就形影不離。"},{"w":"invalid","p":"adj.","d":"not accepted by law or by the rules","c":"無效的","s":"Your ticket is invalid because the date on it has passed.","t":"你的票無效，因為上面的日期已過。"},{"w":"magnify","p":"v.","d":"to make something look bigger than it is","c":"放大","s":"This glass can magnify the tiny letters so that Grandpa can read them.","t":"這片鏡片能把小字放大，讓爺爺看得清楚。"},{"w":"mainstream","p":"n.","d":"the ideas and ways of living that most people accept","c":"主流","s":"Electric cars are now moving into the mainstream of the car market.","t":"電動車現在正進入汽車市場的主流。"},{"w":"microbe","p":"n.","d":"a very small living thing that can only be seen with a microscope","c":"微生物","s":"A single microbe in dirty water can make a person very sick.","t":"髒水裡的一個微生物就可能讓人病得很重。"},{"w":"minor","p":"adj.","d":"small and not serious","c":"輕微的；次要的","s":"It was only a minor accident, and nobody was hurt.","t":"那只是一起輕微的事故，沒有人受傷。"},{"w":"negligible","p":"adj.","d":"so small that it is not important","c":"微不足道的","s":"The difference in price is negligible, only two dollars.","t":"價差微不足道，只有兩塊錢。"},{"w":"paralysis","p":"n.","d":"the loss of the ability to move part of the body","c":"癱瘓","s":"The accident caused paralysis in both of his legs.","t":"那起事故造成他雙腿癱瘓。"},{"w":"pest","p":"n.","d":"an insect or small animal that damages plants or food","c":"害蟲","s":"The farmer sprayed his crops to kill every pest that eats the leaves.","t":"農夫為作物噴藥，殺死每一種吃葉子的害蟲。"},{"w":"prevail","p":"v.","d":"to win in the end","c":"獲勝；佔上風","s":"We believe that truth will prevail over lies.","t":"我們相信真理終將戰勝謊言。"},{"w":"pursuit","p":"n.","d":"the act of trying to get or catch something","c":"追求；追趕","s":"Many people move to big cities in pursuit of a better life.","t":"許多人為了追求更好的生活而搬到大城市。"},{"w":"rupture","p":"v.","d":"to break or burst open suddenly","c":"破裂","s":"The old water pipe may rupture if the pressure gets too high.","t":"如果壓力太高，舊水管可能會破裂。"},{"w":"savage","p":"adj.","d":"very violent or cruel","c":"兇猛的；殘暴的","s":"The sheep were killed in a savage attack by wild dogs.","t":"那些羊在野狗的兇猛攻擊中喪生。"},{"w":"stun","p":"v.","d":"to shock someone so much that they cannot react","c":"使震驚","s":"The news of his sudden death will stun everyone who knew him.","t":"他驟逝的消息會讓所有認識他的人震驚。"},{"w":"susceptible","p":"adj.","d":"likely to be affected by something","c":"易受影響的；易得病的","s":"Young children are more susceptible to colds than adults are.","t":"幼兒比成人更容易感冒。"}]},{"unit":24,"theme":"advocate – unrest","cards":[{"w":"advocate","p":"v.","d":"to support an idea or plan publicly","c":"提倡；主張","s":"Many doctors advocate eating less meat and more vegetables.","t":"許多醫生提倡少吃肉、多吃蔬菜。"},{"w":"albeit","p":"conj.","d":"although","c":"儘管；雖然","s":"He finished the race, albeit in last place.","t":"他跑完了比賽，儘管是最後一名。"},{"w":"authorize","p":"v.","d":"to give official permission for something","c":"授權；批准","s":"Only the manager can authorize payments of more than ten thousand dollars.","t":"只有經理能批准超過一萬元的付款。"},{"w":"civilian","p":"n.","d":"a person who is not a member of the army or the police","c":"平民","s":"Not one civilian was hurt in the fighting, only soldiers.","t":"沒有任何平民在戰鬥中受傷，只有士兵。"},{"w":"commodity","p":"n.","d":"something that is bought and sold","c":"商品；原物料","s":"Oil is the most important commodity that the country sells abroad.","t":"石油是該國銷往海外最重要的商品。"},{"w":"communicate","p":"v.","d":"to share information or ideas with someone","c":"溝通","s":"Deaf people often communicate with their hands.","t":"聾人常用手語溝通。"},{"w":"conquest","p":"n.","d":"the act of taking control of a country by force","c":"征服","s":"The Spanish conquest of Mexico took place in the sixteenth century.","t":"西班牙征服墨西哥發生在十六世紀。"},{"w":"disclose","p":"v.","d":"to make something known that was secret","c":"透露；公開","s":"The company refused to disclose how much it paid for the land.","t":"公司拒絕透露買這塊地花了多少錢。"},{"w":"dynamics","p":"n.","d":"the way in which people or things behave and react to each other","c":"動態；相互作用","s":"A new baby changes the dynamics of the whole family.","t":"新生兒會改變整個家庭的互動關係。"},{"w":"enroll","p":"v.","d":"to officially join a school or course","c":"註冊；報名","s":"I want to enroll in a Japanese class this summer.","t":"今年夏天我想報名日語課。"},{"w":"envious","p":"adj.","d":"wanting something that someone else has","c":"羨慕的；嫉妒的","s":"The other children were envious of his new bicycle.","t":"其他孩子很羨慕他的新腳踏車。"},{"w":"festive","p":"adj.","d":"cheerful and suitable for a celebration","c":"節慶的；歡樂的","s":"The streets looked festive with colorful lights and flags.","t":"街道掛滿彩燈和旗幟，洋溢著節慶氣氛。"},{"w":"indicate","p":"v.","d":"to show that something is true or exists","c":"顯示；指出","s":"The dark clouds indicate that it will rain soon.","t":"烏雲顯示很快就要下雨了。"},{"w":"lentil","p":"n.","d":"a small, round, flat seed that is cooked and eaten","c":"扁豆","s":"A single lentil is tiny, but a bowl of them makes a filling soup.","t":"一顆扁豆很小，但一碗扁豆就能煮成飽足的湯。"},{"w":"marshal","p":"v.","d":"to gather and organize people or things","c":"集結；整頓","s":"The general began to marshal his soldiers for the attack.","t":"將軍開始集結士兵準備進攻。"},{"w":"morale","p":"n.","d":"how confident and happy a group of people feels","c":"士氣","s":"The team's morale was high after it won three games in a row.","t":"球隊三連勝後士氣高昂。"},{"w":"mood","p":"n.","d":"the way you feel at a particular time","c":"心情；情緒","s":"He is in a good mood today because he passed his exam.","t":"他今天心情很好，因為考試通過了。"},{"w":"prophecy","p":"n.","d":"a statement that something will happen in the future","c":"預言","s":"The old woman's prophecy that the king would lose the war came true.","t":"那位老婦人說國王會戰敗的預言成真了。"},{"w":"senate","p":"n.","d":"one of the two groups that make laws in some countries","c":"參議院","s":"The new law must be passed by the senate before the president signs it.","t":"這項新法律必須先由參議院通過，總統才能簽署。"},{"w":"unrest","p":"n.","d":"a situation in which people are angry and may fight or protest","c":"動亂；不安","s":"High food prices caused unrest in several cities.","t":"糧價高漲在數個城市引發動亂。"}]},{"unit":25,"theme":"certify – widespread","cards":[{"w":"certify","p":"v.","d":"to say officially that something is true or correct","c":"證明；認證","s":"Two doctors must certify that the patient is healthy enough to fly.","t":"必須由兩位醫生證明病人健康狀況足以搭機。"},{"w":"coherent","p":"adj.","d":"clear and easy to understand","c":"有條理的；連貫的","s":"He was so tired that he could not give a coherent answer.","t":"他累到無法給出有條理的回答。"},{"w":"collaborate","p":"v.","d":"to work together with someone","c":"合作","s":"The two singers will collaborate on a new song this year.","t":"這兩位歌手今年將合作一首新歌。"},{"w":"compile","p":"v.","d":"to collect information and put it together in a list or book","c":"彙編；編輯","s":"It took her three years to compile the dictionary.","t":"她花了三年編纂這本字典。"},{"w":"curb","p":"v.","d":"to control or limit something","c":"抑制；控制","s":"The government raised taxes on cars to curb air pollution.","t":"政府提高汽車稅以抑制空氣污染。"},{"w":"diagnose","p":"v.","d":"to find out what illness a person has","c":"診斷","s":"The doctors could not diagnose his illness until they tested his blood.","t":"醫生直到驗血後才能診斷出他的病。"},{"w":"enact","p":"v.","d":"to make something into a law","c":"制定（法律）","s":"The government plans to enact a law against smoking in parks.","t":"政府計畫制定禁止在公園吸菸的法律。"},{"w":"federation","p":"n.","d":"a group of states or organizations that have joined together","c":"聯邦；聯盟","s":"The federation of ten small states has one central government.","t":"這個由十個小州組成的聯邦有一個中央政府。"},{"w":"gross","p":"n.","d":"the total amount before anything is taken away","c":"總額；毛收入","s":"The film's opening weekend gross was over ten million dollars.","t":"這部電影首週末的總票房超過一千萬美元。"},{"w":"humane","p":"adj.","d":"kind and caring toward people and animals","c":"人道的；仁慈的","s":"The zoo was praised for its humane treatment of animals.","t":"這家動物園因人道對待動物而受到讚揚。"},{"w":"needy","p":"adj.","d":"very poor; without enough food or money","c":"貧困的","s":"The charity gives food and clothes to needy families.","t":"這個慈善機構提供食物和衣服給貧困家庭。"},{"w":"onset","p":"n.","d":"the beginning of something, especially something bad","c":"開始；發作","s":"The onset of winter brought heavy snow to the mountains.","t":"冬天一開始就為山區帶來大雪。"},{"w":"pledge","p":"v.","d":"to make a serious promise","c":"承諾；保證","s":"Many countries pledge to cut pollution by half within ten years.","t":"許多國家承諾在十年內將污染減半。"},{"w":"prohibit","p":"v.","d":"to say that something is not allowed by law or rule","c":"禁止","s":"Most hospitals prohibit smoking inside their buildings.","t":"大多數醫院禁止在院內吸菸。"},{"w":"render","p":"v.","d":"to cause someone or something to be in a certain state","c":"使成為","s":"The shocking news seemed to render him unable to speak.","t":"這個驚人的消息似乎讓他說不出話。"},{"w":"smallpox","p":"n.","d":"a serious disease that caused spots on the skin and killed many people in the past","c":"天花","s":"Thanks to vaccines, nobody in the world has smallpox today.","t":"多虧疫苗，現在世界上已經沒有人得天花。"},{"w":"transform","p":"v.","d":"to change something completely","c":"改變；使轉變","s":"A coat of fresh paint can transform an old room.","t":"刷上一層新油漆能讓舊房間煥然一新。"},{"w":"transmit","p":"v.","d":"to send a signal or pass something from one place or person to another","c":"傳送；傳播","s":"Some insects transmit diseases from one person to another.","t":"有些昆蟲會把疾病從一個人傳給另一個人。"},{"w":"vow","p":"v.","d":"to promise very seriously to do something","c":"發誓","s":"Every New Year, I vow to exercise more.","t":"每年新年我都發誓要多運動。"},{"w":"widespread","p":"adj.","d":"happening or existing in many places","c":"普遍的；廣泛的","s":"The storm caused widespread damage across the whole island.","t":"暴風雨在全島造成大範圍的損害。"}]},{"unit":26,"theme":"adhere – voluntary","cards":[{"w":"adhere","p":"v.","d":"to follow a rule; to stick to something","c":"遵守；黏附","s":"All players must adhere to the rules of the game.","t":"所有球員都必須遵守比賽規則。"},{"w":"administer","p":"v.","d":"to manage something; to give medicine to someone","c":"管理；施用（藥物）","s":"Only a nurse may administer this medicine to patients.","t":"只有護理師可以給病人施用這種藥。"},{"w":"compassionate","p":"adj.","d":"feeling pity for others and wanting to help them","c":"有同情心的","s":"The compassionate nurse held the old man's hand all night.","t":"那位有同情心的護理師整夜握著老人的手。"},{"w":"contaminate","p":"v.","d":"to make something dirty or dangerous","c":"污染","s":"Chemicals from the factory could contaminate the river.","t":"工廠的化學物質可能污染河川。"},{"w":"deficiency","p":"n.","d":"a lack of something that is needed","c":"缺乏；不足","s":"A deficiency of vitamin C can make your gums bleed.","t":"缺乏維生素C會使牙齦出血。"},{"w":"emphasis","p":"n.","d":"special importance given to something","c":"強調；重點","s":"Our school puts great emphasis on reading and writing.","t":"我們學校非常重視閱讀和寫作。"},{"w":"epidemic","p":"n.","d":"a disease that spreads quickly to many people","c":"流行病；疫情","s":"The flu epidemic closed schools across the country for two weeks.","t":"流感疫情使全國學校停課兩週。"},{"w":"hazard","p":"n.","d":"something that can be dangerous","c":"危險；危害","s":"Ice on the road is a serious hazard for drivers.","t":"路面結冰對駕駛人是嚴重的危險。"},{"w":"imperative","p":"adj.","d":"extremely important and needing to be done now","c":"必要的；緊急的","s":"It is imperative that you see a doctor right away.","t":"你必須馬上去看醫生。"},{"w":"intestines","p":"n.","d":"the long tubes in the body that carry food away from the stomach","c":"腸","s":"Food moves slowly through the intestines after it leaves the stomach.","t":"食物離開胃之後緩慢通過腸道。"},{"w":"manifest","p":"v.","d":"to show something clearly","c":"顯現；表明","s":"Signs of the illness usually manifest themselves within a week.","t":"這種病的徵狀通常在一週內顯現。"},{"w":"overcrowded","p":"adj.","d":"having too many people in one place","c":"過度擁擠的","s":"The overcrowded bus had no room for even one more passenger.","t":"那輛擠爆的公車連一名乘客也擠不上去了。"},{"w":"practitioner","p":"n.","d":"a person who works as a doctor or lawyer","c":"開業者；從業人員","s":"She is a medical practitioner with twenty years of experience.","t":"她是有二十年經驗的執業醫師。"},{"w":"provision","p":"n.","d":"the act of giving people something they need","c":"供應；提供","s":"The provision of clean water is the first job after a flood.","t":"水災後的首要工作是供應乾淨的水。"},{"w":"replenish","p":"v.","d":"to fill something up again","c":"補充","s":"We stopped at the river to replenish our water bottles.","t":"我們在河邊停下來把水壺重新裝滿。"},{"w":"reverse","p":"v.","d":"to go backward; to change something to its opposite","c":"倒退；使反轉","s":"He had to reverse the car slowly out of the narrow street.","t":"他必須慢慢把車倒出那條窄巷。"},{"w":"sterile","p":"adj.","d":"completely clean and free from germs","c":"無菌的","s":"Doctors must use sterile tools during an operation.","t":"醫生手術時必須使用無菌器械。"},{"w":"upgrade","p":"v.","d":"to improve something by making it newer or better","c":"升級","s":"I need to upgrade my computer because it is too slow.","t":"我需要升級電腦，因為它太慢了。"},{"w":"viable","p":"adj.","d":"able to work or succeed","c":"可行的","s":"Solar power is a viable choice in sunny countries.","t":"在陽光充足的國家，太陽能是可行的選擇。"},{"w":"voluntary","p":"adj.","d":"done because you want to, not because you must","c":"自願的","s":"Joining the after-school club is voluntary, so nobody has to come.","t":"參加課後社團是自願的，所以沒有人非來不可。"}]},{"unit":27,"theme":"airway – utensil","cards":[{"w":"airway","p":"n.","d":"the tube in the throat that air passes through when you breathe","c":"呼吸道","s":"A piece of food blocked the child's airway, and he could not breathe.","t":"一塊食物堵住那孩子的呼吸道，他無法呼吸。"},{"w":"Almighty","p":"n.","d":"a name for God, who has power over everything","c":"上帝；全能者","s":"The villagers prayed to the Almighty for rain.","t":"村民向上帝祈求下雨。"},{"w":"advent","p":"n.","d":"the arrival of something important","c":"出現；到來","s":"Before the advent of the Internet, people wrote letters by hand.","t":"在網際網路出現之前，人們用手寫信。"},{"w":"cycle","p":"n.","d":"a set of events that happen again and again in the same order","c":"循環；週期","s":"The cycle of the seasons repeats every year.","t":"四季的循環每年重複。"},{"w":"definitive","p":"adj.","d":"final and not able to be changed","c":"決定性的；最終的","s":"We are still waiting for a definitive answer from the manager.","t":"我們還在等經理的最終答覆。"},{"w":"equate","p":"v.","d":"to think that two things are the same","c":"等同；視為相等","s":"Many people equate money with happiness, but they are wrong.","t":"許多人把金錢等同於快樂，但他們錯了。"},{"w":"found","p":"v.","d":"to start a school, company, or city","c":"創立；建立","s":"The two brothers plan to found a school for poor children.","t":"這對兄弟計畫為貧童創辦一所學校。"},{"w":"ideology","p":"n.","d":"a set of ideas that a political or economic system is based on","c":"意識形態","s":"The two parties have a very different ideology about taxes.","t":"這兩個政黨在稅制上有非常不同的意識形態。"},{"w":"inhale","p":"v.","d":"to breathe in","c":"吸入","s":"Close your eyes and inhale slowly through your nose.","t":"閉上眼睛，用鼻子慢慢吸氣。"},{"w":"invoke","p":"v.","d":"to use a law or rule as a reason for doing something","c":"援引；祈求","s":"The president may invoke a special law during a national emergency.","t":"國家緊急狀況時，總統可以援引一項特別法。"},{"w":"lunar","p":"adj.","d":"relating to the moon","c":"月球的；陰曆的","s":"The first lunar landing took place in 1969.","t":"首次登月發生在1969年。"},{"w":"novelty","p":"n.","d":"the quality of being new and unusual","c":"新奇；新鮮感","s":"The novelty of the new toy wore off after only two days.","t":"新玩具的新鮮感才兩天就消失了。"},{"w":"outmoded","p":"adj.","d":"no longer modern or useful","c":"過時的","s":"The factory still uses outmoded machines from the 1960s.","t":"那家工廠仍在使用1960年代的過時機器。"},{"w":"personalize","p":"v.","d":"to change something so that it is right for one person","c":"個人化","s":"You can personalize the phone case with your own name and photo.","t":"你可以用自己的名字和照片把手機殼個人化。"},{"w":"psychiatric","p":"adj.","d":"relating to the treatment of mental illness","c":"精神病學的；精神科的","s":"He spent a month in a psychiatric hospital after the war.","t":"戰後他在精神科醫院住了一個月。"},{"w":"psychiatry","p":"n.","d":"the study and treatment of mental illness","c":"精神病學","s":"After medical school, she chose to work in psychiatry.","t":"醫學院畢業後，她選擇從事精神醫學。"},{"w":"reflex","p":"n.","d":"a quick movement that your body makes without thinking","c":"反射動作","s":"Closing your eyes when something flies at your face is a reflex.","t":"有東西飛向臉時閉上眼睛是一種反射動作。"},{"w":"seizure","p":"n.","d":"a sudden attack of illness in which the body shakes","c":"發作；癲癇發作","s":"The boy fell to the floor and had a seizure during class.","t":"那個男孩上課時倒在地上發作抽搐。"},{"w":"session","p":"n.","d":"a period of time used for one activity","c":"一段時間；一節（課、活動）","s":"Each training session lasts ninety minutes.","t":"每節訓練課持續九十分鐘。"},{"w":"utensil","p":"n.","d":"a tool used in the kitchen or house","c":"器具；用具","s":"A wooden spoon is the most useful utensil in my kitchen.","t":"木湯匙是我廚房裡最實用的器具。"}]},{"unit":28,"theme":"allocate – wavy","cards":[{"w":"allocate","p":"v.","d":"to decide officially how much of something each person or purpose will get","c":"分配；撥出","s":"The city will allocate more money to public schools next year.","t":"市政府明年將撥更多經費給公立學校。"},{"w":"appetizing","p":"adj.","d":"looking or smelling good to eat","c":"開胃的；促進食慾的","s":"The appetizing smell of fresh bread made everyone hungry.","t":"新鮮麵包誘人的香味讓大家都餓了。"},{"w":"assign","p":"v.","d":"to give someone a job or task","c":"指派；分配","s":"The teacher will assign a partner to each student.","t":"老師會為每位學生指派一位夥伴。"},{"w":"cavity","p":"n.","d":"a hole, especially one in a tooth","c":"洞；蛀牙洞","s":"The dentist found a cavity in one of my back teeth.","t":"牙醫在我的一顆後牙發現蛀洞。"},{"w":"clockwise","p":"adv.","d":"in the same direction as the hands of a clock","c":"順時針方向地","s":"Turn the key clockwise to lock the door.","t":"把鑰匙順時針轉動來鎖門。"},{"w":"concentric","p":"adj.","d":"having the same center","c":"同心的","s":"A stone dropped into a lake makes concentric circles on the water.","t":"石頭丟進湖裡會在水面形成同心圓。"},{"w":"courtesy","p":"n.","d":"polite behavior","c":"禮貌","s":"The clerk treated every customer with courtesy and respect.","t":"那位店員以禮貌和尊重對待每位顧客。"},{"w":"crisp","p":"adj.","d":"pleasantly hard and dry; fresh and firm","c":"脆的","s":"She bit into a crisp green apple.","t":"她咬了一口脆綠的蘋果。"},{"w":"discord","p":"n.","d":"disagreement between people","c":"不和；爭執","s":"Money problems caused discord between the two brothers.","t":"金錢問題造成兩兄弟不和。"},{"w":"generate","p":"v.","d":"to produce energy, ideas, or money","c":"產生","s":"Wind farms generate electricity without burning coal.","t":"風力發電廠不用燒煤就能發電。"},{"w":"item","p":"n.","d":"a single thing on a list or in a group","c":"物品；項目","s":"The most expensive item on the menu is the steak.","t":"菜單上最貴的品項是牛排。"},{"w":"interchange","p":"n.","d":"the act of sharing or exchanging ideas or things","c":"交換；交流","s":"The meeting allowed a free interchange of ideas between teachers and parents.","t":"這場會議讓老師和家長能自由交流意見。"},{"w":"multicultural","p":"adj.","d":"including people of many different cultures","c":"多元文化的","s":"Canada is a multicultural country with people from all over the world.","t":"加拿大是多元文化國家，有來自世界各地的人。"},{"w":"omission","p":"n.","d":"something that has been left out","c":"遺漏；省略","s":"The omission of her name from the guest list was a mistake.","t":"賓客名單上漏了她的名字是個失誤。"},{"w":"oversee","p":"v.","d":"to watch a job or activity to make sure it is done correctly","c":"監督","s":"An experienced engineer will oversee the building of the bridge.","t":"一位資深工程師將監督這座橋的興建。"},{"w":"pierce","p":"v.","d":"to make a hole in something with a sharp point","c":"刺穿","s":"The nail was sharp enough to pierce the thick leather.","t":"那根釘子尖得足以刺穿厚皮革。"},{"w":"select","p":"v.","d":"to choose something carefully from a group","c":"挑選","s":"Please select one book from the list and read it this month.","t":"請從書單挑選一本書，在這個月讀完。"},{"w":"structure","p":"n.","d":"the way that the parts of something are put together; a building","c":"結構；建築物","s":"The bridge is a steel structure that is two hundred meters long.","t":"這座橋是長兩百公尺的鋼結構。"},{"w":"visual","p":"adj.","d":"relating to seeing","c":"視覺的","s":"The teacher uses pictures and other visual aids in her lessons.","t":"老師上課時使用圖片和其他視覺輔助教具。"},{"w":"wavy","p":"adj.","d":"having curves like waves","c":"波浪狀的","s":"She has long, wavy brown hair.","t":"她有一頭棕色的長捲髮。"}]},{"unit":29,"theme":"conversion – synthesis","cards":[{"w":"conversion","p":"n.","d":"the act of changing something from one form or use to another","c":"轉換；改建","s":"The conversion of the old factory into apartments took two years.","t":"把舊工廠改建成公寓花了兩年。"},{"w":"cram","p":"v.","d":"to push too many things into a small space","c":"塞滿；硬塞","s":"Don't try to cram all your clothes into one small bag.","t":"別想把所有衣服硬塞進一個小包包。"},{"w":"defer","p":"v.","d":"to delay something until a later time","c":"延期；推遲","s":"She decided to defer her studies for a year to travel.","t":"她決定把學業延後一年去旅行。"},{"w":"export","p":"v.","d":"to sell goods to another country","c":"出口；輸出","s":"Taiwan and Thailand export fruit to many countries.","t":"台灣和泰國出口水果到許多國家。"},{"w":"fume","p":"n.","d":"smoke or gas that smells strong and is harmful to breathe","c":"煙霧；廢氣","s":"A thick fume of black smoke rose from the old truck.","t":"一股濃濃的黑煙從舊卡車冒出。"},{"w":"habitual","p":"adj.","d":"done often, as a habit","c":"習慣性的","s":"His habitual lateness finally cost him his job.","t":"他習慣性遲到，終於讓他丟了工作。"},{"w":"justify","p":"v.","d":"to show that something is right or reasonable","c":"證明…合理；為…辯解","s":"Nothing can justify hitting a child.","t":"沒有任何理由能把打小孩合理化。"},{"w":"notwithstanding","p":"prep.","d":"in spite of","c":"儘管","s":"Notwithstanding the bad weather, the game went on as planned.","t":"儘管天氣惡劣，比賽仍照計畫進行。"},{"w":"output","p":"n.","d":"the amount of something that a person, machine, or factory produces","c":"產量；輸出","s":"The factory doubled its output after buying new machines.","t":"買了新機器後，工廠的產量加倍。"},{"w":"overpopulation","p":"n.","d":"the problem of having too many people living in one place","c":"人口過剩","s":"Overpopulation makes it hard for some cities to provide enough housing.","t":"人口過剩使一些城市難以提供足夠的住房。"},{"w":"patent","p":"n.","d":"the legal right to be the only one to make or sell an invention","c":"專利","s":"She holds the patent on a new kind of battery.","t":"她擁有一種新型電池的專利。"},{"w":"penalize","p":"v.","d":"to punish someone for breaking a rule","c":"處罰","s":"The teacher will penalize students who hand in their homework late.","t":"老師會處罰遲交作業的學生。"},{"w":"petroleum","p":"n.","d":"oil found under the ground and used to make gas and plastic","c":"石油","s":"Plastic and gasoline are both made from petroleum.","t":"塑膠和汽油都是由石油製成。"},{"w":"region","p":"n.","d":"a large area of land","c":"地區；區域","s":"Tea grows well in the mountain region of central Taiwan.","t":"茶葉在台灣中部山區長得很好。"},{"w":"scrap","p":"n.","d":"a small piece of paper or cloth","c":"碎片；小塊","s":"He wrote her phone number on a scrap of paper.","t":"他把她的電話號碼寫在一張碎紙上。"},{"w":"sector","p":"n.","d":"one part of a country's economy","c":"部門；產業","s":"Thousands of people work in the tourism sector of the economy.","t":"成千上萬的人在觀光產業工作。"},{"w":"subscribe","p":"v.","d":"to pay to receive a magazine or service regularly","c":"訂閱","s":"I subscribe to two magazines and a music service.","t":"我訂閱兩本雜誌和一個音樂服務。"},{"w":"subsist","p":"v.","d":"to stay alive with only a small amount of food or money","c":"勉強維生","s":"The villagers subsist mainly on rice and fish.","t":"村民主要靠米和魚維生。"},{"w":"suspend","p":"v.","d":"to stop something for a short time","c":"暫停；使停學","s":"Heavy rain forced the airport to suspend all flights.","t":"大雨迫使機場暫停所有航班。"},{"w":"synthesis","p":"n.","d":"a mix of different ideas or things into a whole","c":"綜合；合成","s":"Her music is a synthesis of jazz and traditional Chinese songs.","t":"她的音樂融合了爵士樂和傳統中國歌曲。"}]},{"unit":30,"theme":"acrobat – vine","cards":[{"w":"acrobat","p":"n.","d":"a person who does difficult tricks with the body, such as jumping and balancing","c":"雜技演員","s":"The acrobat walked across a rope high above the crowd.","t":"那位雜技演員在觀眾上方高處走鋼索。"},{"w":"advocacy","p":"n.","d":"public support for an idea or a group","c":"提倡；擁護","s":"She is famous for her advocacy of animal rights.","t":"她以提倡動物權利聞名。"},{"w":"communal","p":"adj.","d":"shared by a group of people","c":"公用的；共有的","s":"The students in the dorm share a communal kitchen.","t":"宿舍的學生共用一間公共廚房。"},{"w":"fluid","p":"adj.","d":"smooth and graceful in movement","c":"流暢的","s":"The dancer's fluid movements were beautiful to watch.","t":"那位舞者流暢的動作十分賞心悅目。"},{"w":"harmonize","p":"v.","d":"to go well together","c":"協調；和諧","s":"The colors of the curtains harmonize well with the sofa.","t":"窗簾的顏色和沙發很協調。"},{"w":"industrious","p":"adj.","d":"working very hard","c":"勤勞的","s":"The industrious student studied for five hours every night.","t":"那位勤奮的學生每晚讀五小時的書。"},{"w":"inventive","p":"adj.","d":"good at thinking of new ideas","c":"有創意的；善於發明的","s":"The inventive cook made a tasty meal from leftover rice and eggs.","t":"那位有創意的廚師用剩飯和蛋做出美味的一餐。"},{"w":"Mandarin","p":"n.","d":"the official language of China and Taiwan","c":"華語；國語","s":"Most people in Taiwan speak Mandarin at school and at work.","t":"台灣大多數人在學校和工作時說華語。"},{"w":"metropolitan","p":"adj.","d":"relating to a big city","c":"大都會的","s":"More than seven million people live in the Taipei metropolitan area.","t":"超過七百萬人住在台北都會區。"},{"w":"mimic","p":"v.","d":"to copy the way someone speaks or acts","c":"模仿","s":"Some birds can mimic the sound of a ringing phone.","t":"有些鳥能模仿電話鈴聲。"},{"w":"misguided","p":"adj.","d":"based on a wrong idea or understanding","c":"被誤導的；判斷錯誤的","s":"His misguided attempt to help only made things worse.","t":"他判斷錯誤的幫忙只讓事情更糟。"},{"w":"rehearse","p":"v.","d":"to practice a play or piece of music before a performance","c":"排練","s":"The actors rehearse every evening for the school play.","t":"演員們每晚為學校話劇排練。"},{"w":"resourceful","p":"adj.","d":"good at finding ways to solve problems","c":"足智多謀的","s":"The resourceful boy fixed his broken bike with a piece of wire.","t":"那個機智的男孩用一段鐵絲修好壞掉的腳踏車。"},{"w":"scorn","p":"v.","d":"to show that you think someone or something is stupid or worthless","c":"輕蔑；瞧不起","s":"You should not scorn people just because they are poor.","t":"你不該只因為別人窮就瞧不起他們。"},{"w":"sensory","p":"adj.","d":"relating to the five senses","c":"感官的","s":"The brain receives sensory information from the eyes, ears, and skin.","t":"大腦從眼睛、耳朵和皮膚接收感官訊息。"},{"w":"statute","p":"n.","d":"a written law","c":"法令；法規","s":"A new statute makes it illegal to use a phone while driving.","t":"一項新法令規定開車時使用手機違法。"},{"w":"technical","p":"adj.","d":"relating to the practical use of machines or science","c":"技術的","s":"The flight was delayed because of a technical problem with the engine.","t":"班機因引擎的技術問題而延誤。"},{"w":"veteran","p":"n.","d":"a person who was a soldier in a war","c":"退伍軍人","s":"The old veteran told us stories about his years in the army.","t":"那位老兵跟我們講他從軍那些年的故事。"},{"w":"villain","p":"n.","d":"the bad character in a story or movie","c":"反派；壞人","s":"In the movie, the villain steals a train full of gold.","t":"電影裡，反派偷走一列滿載黃金的火車。"},{"w":"vine","p":"n.","d":"a plant with long stems that climbs up walls or trees","c":"藤蔓","s":"A green vine climbed up the wall of the old house.","t":"一條綠色藤蔓爬上老屋的牆。"}]}];
